from datetime import datetime, timedelta
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)


def plan_reminders(appointments, now):
    """Return appointment reminders scheduled in Europe/Dublin local time."""
    now = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        appointment_at = next(
            appointment[key]
            for key in ("appointment_datetime", "starts_at", "datetime")
            if key in appointment
        ).astimezone(_DUBLIN)

        customer = appointment.get("customer", {})
        name = customer.get("name", appointment.get("customer_name", ""))
        phone = customer.get("phone", appointment.get("phone"))
        email = customer.get("email", appointment.get("email"))
        country = customer.get("country", appointment.get("country"))
        signature = "Grzegorz Szczepański" if country == "PL" else "Siobhán Ní Dhuibhir"

        when = appointment_at.strftime("%Y-%m-%d")
        at = appointment_at.strftime("%H:%M")
        for lead in (timedelta(hours=48), timedelta(hours=2)):
            send_at = appointment_at - lead
            if send_at < now:
                send_at = now

            local = send_at.astimezone(_DUBLIN)
            if local.hour >= 21:
                local = local.replace(hour=20, minute=0, second=0, microsecond=0)
            elif local.hour < 8:
                local = (local - timedelta(days=1)).replace(
                    hour=20, minute=0, second=0, microsecond=0
                )
            send_at = local
            if send_at < now:
                if now.hour < 8 or now.hour >= 21:
                    send_at = (now + timedelta(days=1)).replace(
                        hour=8, minute=0, second=0, microsecond=0
                    )
                else:
                    send_at = now

            channel = (
                "sms"
                if phone and not customer.get(
                    "optout_sms_v2", appointment.get("optout_sms_v2", False)
                )
                else "email"
            )
            text = f"Hi {name}, reminder: your appointment is on {when} at {at}. {signature}"
            if channel == "sms" and len(text) > 160:
                fixed = f"Hi , reminder: your appointment is on {when} at {at}. {signature}"
                name = name[: max(0, 160 - len(fixed))]
                text = f"Hi {name}, reminder: your appointment is on {when} at {at}. {signature}"
                if len(text) > 160:
                    text = fixed[: 160 - len(signature)] + signature

            reminder = {
                "appointment_id": appointment.get("appointment_id", appointment.get("id")),
                "channel": channel,
                "send_at": send_at,
                "text": text,
            }
            reminders.append(reminder)
            contact = phone if channel == "sms" else "[email address redacted]"
            _LOG.info(
                "Planned reminder for %s via %s to %s",
                name or "customer",
                channel,
                contact or "[contact unavailable]",
            )

    return sorted(reminders, key=lambda reminder: reminder["send_at"])

import logging
from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)


def _aware_datetime(value):
    return isinstance(value, datetime) and value.tzinfo is not None and value.utcoffset() is not None


def _contact_hint(channel, contact):
    if channel == "sms":
        digits = "".join(char for char in str(contact) if char.isdigit())
        return f"phone ending {digits[-2:]}" if digits else "phone ending **"
    return "email"


def _quiet_hours(send_at):
    local = send_at.astimezone(_DUBLIN)
    if local.hour >= 21 or local.hour < 8:
        return local.replace(hour=20, minute=0, second=0, microsecond=0)
    return local


def _message(name, starts_at, signature, sms):
    local_start = starts_at.astimezone(_DUBLIN)
    date = f"{local_start.day} {local_start.strftime('%B %Y')}"
    time = local_start.strftime("%H:%M")
    base = f"Appointment: {date} {time}. {signature}"
    if not sms:
        return f"{name}, {base}" if name else base

    prefix = f"{name}, " if name else ""
    available = 160 - len(base)
    if available <= 0:
        return base[:160]
    return f"{prefix[:available]}{base}"


def plan_reminders(appointments, now):
    """Return deliverable appointment reminders, ordered by send time."""
    if not _aware_datetime(now):
        raise ValueError("now must be timezone-aware")
    now = now.astimezone(_DUBLIN)
    planned = []

    for index, appointment in enumerate(appointments):
        try:
            if not isinstance(appointment, dict):
                raise ValueError("appointment is not a dictionary")
            for field in ("id", "customer_name", "country", "status", "starts_at"):
                if field not in appointment:
                    raise ValueError(f"missing {field}")
            starts_at = appointment["starts_at"]
            if not _aware_datetime(starts_at):
                raise ValueError("starts_at is not timezone-aware")
            if appointment["status"] == "cancelled":
                continue

            phone = appointment.get("phone")
            opted_out = bool(appointment.get("optout_sms_v2", False))
            if phone and not opted_out:
                channel, contact = "sms", phone
            else:
                contact = appointment.get("email")
                if not contact or not str(contact).strip():
                    continue
                channel = "email"

            signature = (
                "Grzegorz Szczepański"
                if appointment["country"] == "PL"
                else "Chevonne Nee Divver"
            )
            local_start = starts_at.astimezone(_DUBLIN)
            for lead_hours in (2, 48):
                send_at = local_start - timedelta(hours=lead_hours)
                if lead_hours == 48 and send_at < now:
                    send_at = now
                send_at = _quiet_hours(send_at)
                if send_at < now:
                    continue

                text = _message(
                    str(appointment["customer_name"]),
                    starts_at,
                    signature,
                    channel == "sms",
                )
                planned.append(
                    (
                        send_at,
                        index,
                        lead_hours,
                        {
                            "appointment_id": appointment["id"],
                            "channel": channel,
                            "send_at": send_at,
                            "text": text,
                        },
                        contact,
                    )
                )
        except (TypeError, ValueError, OverflowError):
            _LOG.warning("Skipping appointment at input index %d due to invalid or missing data", index)

    planned.sort(key=lambda item: (item[0], item[1], item[2]))
    reminders = []
    for _, _, _, reminder, contact in planned:
        _LOG.info(
            "Planned reminder for appointment %s via %s to %s",
            reminder["appointment_id"],
            reminder["channel"],
            _contact_hint(reminder["channel"], contact),
        )
        reminders.append(reminder)
    return reminders

from datetime import datetime, time, timedelta
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_SIGNATURE_DEFAULT = "Chevonne Nee Divver"
_SIGNATURE_PL = "Grzegorz Szczepański"
_LOG = logging.getLogger(__name__)


def _aware_datetime(value):
    if not isinstance(value, datetime):
        raise ValueError("Appointment datetime is missing or invalid")
    try:
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError
    except Exception:
        raise ValueError("Appointment datetime must be timezone-aware") from None
    return value


def _message(name, date_text, time_text, signature, sms):
    def build(customer):
        greeting = f"Hi {customer}, " if customer else ""
        return f"{greeting}your appointment is on {date_text} at {time_text}. {signature}"

    text = build(name)
    if sms and len(text) > 160:
        text = build("")
    if sms and len(text) > 160:
        raise ValueError("SMS reminder text exceeds 160 characters")
    return text


def plan_reminders(appointments, now):
    """Return chronologically ordered reminders for valid, non-cancelled appointments."""
    now = _aware_datetime(now)
    reminders = []

    for appointment in appointments:
        if not isinstance(appointment, dict):
            raise ValueError("Appointment record is invalid")
        if appointment.get("status") == "cancelled":
            continue

        try:
            starts_at = _aware_datetime(appointment["starts_at"])
            appointment_id = appointment["id"]
            name = appointment.get("customer_name") or ""
            phone = appointment.get("phone")
            email = appointment.get("email")
            opted_out = appointment["optout_sms_v2"]
            country = appointment.get("country")
        except (KeyError, TypeError):
            raise ValueError("Appointment record is missing required data") from None

        if not isinstance(opted_out, bool):
            raise ValueError("SMS preference must be a boolean")

        use_sms = bool(phone) and not opted_out
        if not use_sms and not email:
            raise ValueError("Appointment has no usable contact details")

        channel = "sms" if use_sms else "email"
        contact = str(phone) if use_sms else "[redacted]"
        signature = _SIGNATURE_PL if country == "PL" else _SIGNATURE_DEFAULT
        local_start = starts_at.astimezone(_DUBLIN)
        date_text = local_start.strftime("%Y-%m-%d")
        time_text = local_start.strftime("%H:%M")

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            target = starts_at - offset
            if offset == timedelta(hours=48) and target < now:
                target = now
            elif target < now:
                continue

            local_target = target.astimezone(_DUBLIN)
            if local_target.time() >= time(21, 0) or local_target.time() < time(8, 0):
                local_target = datetime.combine(
                    local_target.date() - timedelta(days=1),
                    time(20, 0),
                    tzinfo=_DUBLIN,
                )
                target = local_target

            if target < now:
                continue

            text = _message(name, date_text, time_text, signature, use_sms)
            reminders.append(
                {
                    "appointment_id": appointment_id,
                    "channel": channel,
                    "send_at": target,
                    "text": text,
                }
            )
            _LOG.info(
                "Planned reminder for %s via %s contact=%s",
                name or "[unnamed customer]",
                channel,
                contact,
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
import logging

DUBLIN = ZoneInfo("Europe/Dublin")
SIGNATURE = "Chevonne Nee Divver"
POLISH_SIGNATURE = "Grzegorz Szczepański"
logger = logging.getLogger(__name__)


def _dublin(dt):
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("datetimes must be timezone-aware")
    return dt.astimezone(DUBLIN)


def _schedule(send_at, now):
    quiet = send_at.time() >= time(21) or send_at.time() < time(8)
    if quiet:
        send_at = send_at.replace(hour=20, minute=0, second=0, microsecond=0)
        if send_at >= now:
            send_at -= timedelta(days=1)

    if send_at < now:
        send_at = now

    if send_at.time() >= time(21) or send_at.time() < time(8):
        send_at = send_at.replace(hour=8, minute=0, second=0, microsecond=0)
        if send_at < now:
            send_at += timedelta(days=1)

    return send_at


def _text(name, starts_at, signature, channel):
    date_text = starts_at.strftime("%d %B %Y")
    time_text = starts_at.strftime("%H:%M")
    suffix = f"Your appointment is on {date_text} at {time_text}. {signature}"
    prefix = f"Hi {name}, " if name else ""
    message = prefix + suffix
    if channel == "sms" and len(message) > 160:
        available = max(0, 160 - len(suffix) - len("Hi , "))
        short_name = (name or "")[:available].rstrip()
        message = f"Hi {short_name}, {suffix}" if short_name else suffix
    return message


def plan_reminders(appointments, now):
    now = _dublin(now)
    reminders = []

    for appointment in appointments:
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        starts_at = _dublin(appointment["starts_at"])
        channel = (
            "sms"
            if appointment.get("phone") and not appointment.get("optout_sms_v2", False)
            else "email"
        )
        signature = (
            POLISH_SIGNATURE if appointment.get("country") == "PL" else SIGNATURE
        )
        name = appointment.get("customer_name", "")
        contact = appointment.get("phone") if channel == "sms" else "[redacted]"

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            target = starts_at - offset
            if target < now:
                if offset == timedelta(hours=48):
                    target = now
                else:
                    continue

            send_at = _schedule(target, now)
            reminder = {
                "appointment_id": appointment["id"],
                "channel": channel,
                "send_at": send_at,
                "text": _text(name, starts_at, signature, channel),
            }
            reminders.append(reminder)
            logger.info(
                "Reminder recipient=%s channel=%s contact=%s",
                name,
                channel,
                contact,
            )

    reminders.sort(key=lambda reminder: reminder["send_at"].astimezone(DUBLIN))
    return reminders

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURES = {
    "PL": "Grzegorz Szczepański",
}


def plan_reminders(appointments, now):
    now = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        if appointment["status"] == "cancelled":
            continue

        channel = (
            "sms"
            if appointment.get("phone") and not appointment.get("optout_sms_v2", False)
            else "email"
        )
        starts_at = appointment["starts_at"].astimezone(_DUBLIN)
        date_time = starts_at.strftime("%Y-%m-%d %H:%M")
        signature = _SIGNATURES.get(appointment.get("country"), "Siobhán Ní Dhuibhir")
        name = str(appointment["customer_name"])
        text = f"Reminder for {name}: appointment on {date_time}. {signature}"

        if channel == "sms" and len(text) > 160:
            suffix = f": appointment on {date_time}. {signature}"
            available = 160 - len("Reminder for ") - len(suffix)
            text = f"Reminder for {name[:max(0, available)]}{suffix}"

        for lead in (timedelta(hours=48), timedelta(hours=2)):
            send_at = max(starts_at - lead, now)

            if time(21) <= send_at.timetz().replace(tzinfo=None) or send_at.hour < 8:
                if send_at.hour < 8:
                    send_at = (send_at - timedelta(days=1)).replace(
                        hour=20, minute=0, second=0, microsecond=0
                    )
                else:
                    send_at = send_at.replace(
                        hour=20, minute=0, second=0, microsecond=0
                    )

                if send_at < now:
                    send_at = (
                        now.replace(hour=8, minute=0, second=0, microsecond=0)
                        if now.hour < 8 or now.hour >= 21
                        else now
                    )

            _LOG.info(
                "Planned reminder for %s via %s to %s",
                name,
                channel,
                appointment.get("phone") if channel == "sms" else "email",
            )
            reminders.append(
                {
                    "appointment_id": appointment["id"],
                    "channel": channel,
                    "send_at": send_at,
                    "text": text,
                }
            )

    return sorted(reminders, key=lambda reminder: reminder["send_at"])

from datetime import datetime, time, timedelta, timezone
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOGGER = logging.getLogger(__name__)


def _require_aware(value, field):
    if not isinstance(value, datetime) or value.utcoffset() is None:
        raise ValueError(f"{field} must be a timezone-aware datetime")


def _quiet_hours(send_at, now_utc):
    local_time = send_at.timetz().replace(tzinfo=None)
    if local_time >= time(21):
        send_at = datetime.combine(send_at.date(), time(20), _DUBLIN)
    elif local_time < time(8):
        send_at = datetime.combine(
            send_at.date() - timedelta(days=1), time(20), _DUBLIN
        )
    if send_at.astimezone(timezone.utc) < now_utc:
        return now_utc.astimezone(_DUBLIN)
    return send_at


def _message(name, date, local_time, signature, sms):
    if name:
        prefix = f"Appointment reminder for {name}: "
    else:
        prefix = "Appointment reminder: "
    suffix = f"{date} at {local_time}. {signature}"
    if sms:
        name_length = max(0, 160 - len(prefix) - len(suffix))
        if name:
            prefix = f"Appointment reminder for {name[:name_length]}: "
        return prefix + suffix
    return prefix + suffix


def plan_reminders(appointments, now):
    """Return scheduled appointment reminders in Europe/Dublin local time."""
    _require_aware(now, "now")
    now_utc = now.astimezone(timezone.utc)
    results = []

    for appointment in appointments:
        if appointment.get("status", "").casefold() == "cancelled":
            continue

        appointment_at = appointment["appointment_at"]
        _require_aware(appointment_at, "appointment_at")
        appointment_utc = appointment_at.astimezone(timezone.utc)
        appointment_local = appointment_utc.astimezone(_DUBLIN)
        date = appointment_local.strftime("%d/%m/%Y")
        local_time = appointment_local.strftime("%H:%M")
        signature = (
            "Grzegorz Szczepański"
            if appointment.get("country") == "PL"
            else "Siobhán Ní Dhuibhir"
        )

        phone = appointment.get("phone", "")
        email = appointment.get("email", "")
        sms = bool(phone) and not appointment.get("optout_sms_v2", False)
        if not sms and not email:
            continue
        channel = "sms" if sms else "email"
        name = appointment.get("customer_name") or ""

        for lead in (timedelta(hours=48), timedelta(hours=2)):
            target_utc = appointment_utc - lead
            if lead == timedelta(hours=2) and target_utc < now_utc:
                continue
            if lead == timedelta(hours=48) and target_utc < now_utc:
                target_utc = now_utc

            send_at = _quiet_hours(target_utc.astimezone(_DUBLIN), now_utc)
            results.append(
                {
                    "appointment_id": appointment.get("appointment_id"),
                    "channel": channel,
                    "send_at": send_at,
                    "text": _message(name, date, local_time, signature, sms),
                }
            )
            _LOGGER.info(
                "Reminder planned for appointment_id=%r via %s to %s",
                appointment.get("appointment_id"),
                channel,
                "phone" if sms else "email",
            )

    results.sort(key=lambda item: item["send_at"].astimezone(timezone.utc))
    return results

from datetime import datetime, timedelta
from logging import getLogger
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = getLogger(__name__)
_SIGNATURE = "Siobhán Ní Dhuibhir"
_POLISH_SIGNATURE = "Grzegorz Szczepański"


def _aware_datetime(value):
    if isinstance(value, str):
        try:
            value = datetime.fromisoformat(value)
        except ValueError:
            return None
    if not isinstance(value, datetime) or value.tzinfo is None:
        return None
    try:
        if value.utcoffset() is None:
            return None
        return value.astimezone(_DUBLIN)
    except (OverflowError, ValueError):
        return None


def _message(name, starts_at, signature, sms):
    date = starts_at.strftime("%Y-%m-%d")
    time = starts_at.strftime("%H:%M")
    prefix = f"Hi {name}, " if name else ""
    body = f"{prefix}reminder: your appointment is on {date} at {time}. {signature}"
    if sms and len(body) > 160:
        fixed = f"Hi , reminder: your appointment is on {date} at {time}. {signature}"
        available = max(0, 160 - len(fixed))
        body = f"Hi {name[:available]}, reminder: your appointment is on {date} at {time}. {signature}"
    return body


def plan_reminders(appointments, now):
    """Return appointment reminders scheduled in Europe/Dublin time."""
    current = _aware_datetime(now)
    if current is None:
        return []

    try:
        entries = iter(appointments)
    except TypeError:
        return []

    reminders = []
    for appointment in entries:
        if not isinstance(appointment, dict):
            continue
        starts_at = _aware_datetime(appointment.get("starts_at"))
        if starts_at is None:
            continue
        if str(appointment.get("status", "")).strip().lower() == "cancelled":
            continue

        phone = appointment.get("phone")
        has_phone = isinstance(phone, str) and bool(phone.strip())
        sms = has_phone and appointment.get("optout_sms_v2") is not True
        channel = "sms" if sms else "email"
        signature = (
            _POLISH_SIGNATURE
            if str(appointment.get("country", "")).strip().upper() == "PL"
            else _SIGNATURE
        )
        raw_name = appointment.get("customer_name")
        name = raw_name.strip() if isinstance(raw_name, str) else ""
        appointment_id = appointment.get("id")

        for lead in (timedelta(hours=48), timedelta(hours=2)):
            try:
                scheduled = starts_at - lead
            except OverflowError:
                continue
            if lead == timedelta(hours=48) and scheduled < current:
                scheduled = current
            if scheduled.hour >= 21 or scheduled.hour < 8:
                try:
                    scheduled = scheduled.replace(hour=20, minute=0, second=0, microsecond=0)
                except (OverflowError, ValueError):
                    continue
            if scheduled < current:
                continue

            reminders.append({
                "appointment_id": appointment_id,
                "channel": channel,
                "send_at": scheduled,
                "text": _message(name, starts_at, signature, channel == "sms"),
            })
            recipient = str(appointment_id).replace("\n", " ") if appointment_id is not None else "unknown"
            contact = "phone on file" if channel == "sms" else "email on file"
            _LOG.info("Reminder planned for appointment %s via %s to %s", recipient, channel, contact)

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
import logging


_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURES = {
    "PL": "Grzegorz Szczepański",
}


def plan_reminders(appointments, now):
    now = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        appointment_at = appointment.get(
            "datetime",
            appointment.get("appointment_datetime", appointment.get("start")),
        )
        if appointment_at is None:
            continue
        appointment_at = appointment_at.astimezone(_DUBLIN)

        phone = appointment.get("phone_number") or appointment.get("phone")
        use_sms = bool(phone) and not appointment.get("optout_sms_v2", False)
        channel = "sms" if use_sms else "email"
        contact = phone if use_sms else "address withheld"

        name = str(appointment.get("customer_name", appointment.get("name", "Customer")))
        signature = _SIGNATURES.get(appointment.get("country"), "Siobhán Ní Dhuibhir")
        date_text = appointment_at.strftime("%Y-%m-%d")
        time_text = appointment_at.strftime("%H:%M")
        text = f"Reminder for your appointment on {date_text} at {time_text}. {signature}"

        if use_sms:
            full_text = f"Hi {name}, {text}"
            if len(full_text) <= 160:
                text = full_text
            else:
                text = f"Hi, {text}"
                if len(text) > 160:
                    text = text[:160]

        for interval in (timedelta(hours=48), timedelta(hours=2)):
            send_at = max(appointment_at - interval, now)
            if send_at.hour >= 21:
                send_at = send_at.replace(hour=20, minute=0, second=0, microsecond=0)
            elif send_at.hour < 8:
                send_at = (send_at - timedelta(days=1)).replace(
                    hour=20, minute=0, second=0, microsecond=0
                )

            if send_at < now or send_at >= appointment_at:
                continue

            reminder = {
                "appointment_id": appointment.get("appointment_id"),
                "channel": channel,
                "send_at": send_at,
                "text": text,
            }
            reminders.append(reminder)
            _LOG.info(
                "Planned reminder for %s via %s to %s",
                appointment.get("appointment_id"),
                channel,
                contact if use_sms else "email (address withheld)",
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, timedelta
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURE = "Grzegorz Szczepański"
_DEFAULT_SIGNATURE = "Siobhán Ní Dhuibhir"


def plan_reminders(appointments, now):
    """Return sorted appointment reminders scheduled in Europe/Dublin time."""
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("now must be timezone-aware")

    now = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        if appointment.get("status") == "cancelled":
            continue

        starts_at = appointment["starts_at"]
        if starts_at.tzinfo is None or starts_at.utcoffset() is None:
            raise ValueError("starts_at must be timezone-aware")
        starts_at = starts_at.astimezone(_DUBLIN)

        channel = (
            "sms"
            if appointment.get("phone") and not appointment.get("optout_sms_v2")
            else "email"
        )
        signature = (
            _SIGNATURE if appointment.get("country") == "PL" else _DEFAULT_SIGNATURE
        )
        date_time = starts_at.strftime("%Y-%m-%d %H:%M")
        name = str(appointment.get("customer_name") or "")
        base = f"Your appointment is on {date_time}. {signature}"
        text = f"Hello {name}, your appointment is on {date_time}. {signature}"

        if channel == "sms" and len(text) > 160:
            available = max(0, 160 - len(f"Hello , {base}"))
            text = f"Hello {name[:available]}, {base}"
            if len(text) > 160:
                text = base

        for index, lead in enumerate((timedelta(hours=48), timedelta(hours=2))):
            original = starts_at - lead
            if original < now:
                if index == 0:
                    original = now
                else:
                    continue

            send_at = original
            if send_at.hour >= 21 or send_at.hour < 8:
                preceding_20 = send_at.replace(
                    hour=20, minute=0, second=0, microsecond=0
                )
                if preceding_20 < send_at and preceding_20 > now:
                    send_at = preceding_20
                else:
                    next_day = send_at.date() + timedelta(days=1)
                    send_at = datetime(
                        next_day.year, next_day.month, next_day.day, 8, 0,
                        tzinfo=_DUBLIN,
                    )

            if send_at < now or send_at >= starts_at:
                continue

            reminders.append({
                "appointment_id": appointment["id"],
                "channel": channel,
                "send_at": send_at,
                "text": text,
            })
            _LOG.info(
                "Planned reminder for %s via %s (%s)",
                name,
                channel,
                "phone" if channel == "sms" else "email",
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, timedelta
from logging import getLogger
from zoneinfo import ZoneInfo

__all__ = ["plan_reminders"]

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = getLogger(__name__)
_SIGNATURE = "Siobhán Ní Dhuibhir"
_POLISH_SIGNATURE = "Grzegorz Szczepański"


def _quiet_adjust(send_at):
    local = send_at.astimezone(_DUBLIN)
    if local.hour < 8:
        return (local - timedelta(days=1)).replace(
            hour=20, minute=0, second=0, microsecond=0
        )
    if local.hour >= 21:
        return local.replace(hour=20, minute=0, second=0, microsecond=0)
    return local


def _message(appointment, sms):
    starts_at = appointment["starts_at"].astimezone(_DUBLIN)
    date = starts_at.strftime("%d %B %Y")
    time = starts_at.strftime("%H:%M")
    signature = (
        _POLISH_SIGNATURE if appointment.get("country") == "PL" else _SIGNATURE
    )
    name = str(appointment.get("customer_name") or "").strip()
    greeting = f"Dear {name}, " if name else ""
    message = f"{greeting}your appointment is on {date} at {time}. {signature}"

    if sms and len(message) > 160:
        fixed = f"your appointment is on {date} at {time}. {signature}"
        prefix = "Dear "
        suffix = ", " if name else ""
        available = 160 - len(fixed) - len(prefix) - len(suffix)
        shortened = name[:max(0, available)].rstrip()
        greeting = f"Dear {shortened}, " if shortened else ""
        message = f"{greeting}{fixed}"
        if len(message) > 160:
            message = fixed
    return message


def plan_reminders(appointments, now):
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("now must be timezone-aware")
    now = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        starts_at = appointment["starts_at"]
        if starts_at.tzinfo is None or starts_at.utcoffset() is None:
            raise ValueError("starts_at must be timezone-aware")
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        phone = appointment.get("phone")
        email = appointment.get("email")
        if phone and appointment.get("optout_sms_v2") is True:
            channel, contact = "sms", phone
        elif email:
            channel, contact = "email", email
        else:
            continue

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            calculated = starts_at.astimezone(_DUBLIN) - offset
            if offset == timedelta(hours=48) and calculated < now:
                calculated = now
            elif calculated < now:
                continue

            send_at = _quiet_adjust(calculated)
            if send_at < now:
                continue

            reminders.append({
                "appointment_id": appointment.get("id"),
                "channel": channel,
                "send_at": send_at,
                "text": _message(appointment, channel == "sms"),
            })
            recipient = appointment.get("customer_name") or "customer"
            logged_contact = str(contact) if channel == "sms" else "address redacted"
            _LOG.info(
                "Reminder for %s via %s to %s",
                recipient,
                channel,
                logged_contact,
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo
import logging

__all__ = ["plan_reminders"]

_DUBLIN = ZoneInfo("Europe/Dublin")
_SIGNATURE_DEFAULT = "Siobhán Ní Dhuibhir"
_SIGNATURE_PL = "Grzegorz Szczepański"

# Product-owner confirmation is required before setting this to True or False.
# True means optout_sms_v2 == True permits SMS; False means it opts the customer out.
_SMS_TRUE_MEANS_ELIGIBLE = None


def _sms_eligible(value):
    if _SMS_TRUE_MEANS_ELIGIBLE is None:
        raise ValueError("sms_policy_unconfirmed")
    return bool(value) is _SMS_TRUE_MEANS_ELIGIBLE


def _masked_contact(channel, contact):
    if channel == "sms":
        digits = "".join(c for c in contact if c.isdigit())
        return f"phone ending {digits[-2:]}" if digits else "phone"
    return "email"


def _message(name, starts_at, signature, channel):
    local_start = starts_at.astimezone(_DUBLIN)
    when = local_start.strftime("%d %B %Y at %H:%M")
    prefix = f"Hi {name.strip()}, " if isinstance(name, str) and name.strip() else "Hello, "
    text = f"{prefix}your appointment is on {when}. {signature}"
    if channel == "sms" and len(text) > 160:
        prefix = "Hello, "
        text = f"{prefix}your appointment is on {when}. {signature}"
        if len(text) > 160:
            text = f"{when}. {signature}"
    return text


def plan_reminders(appointments, now):
    """Plan reminders; send_at values are timezone-aware UTC datetimes."""
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("now must be timezone-aware")
    now_utc = now.astimezone(timezone.utc)
    reminders = []

    for index, appointment in enumerate(appointments):
        try:
            required = (
                "id", "customer_name", "email", "phone", "country", "status",
                "starts_at", "optout_sms_v2",
            )
            if not isinstance(appointment, dict) or any(k not in appointment for k in required):
                raise ValueError("missing_fields")
            appointment_id = appointment["id"]
            if appointment_id is None or not str(appointment_id).strip():
                raise ValueError("invalid_id")
            starts_at = appointment["starts_at"]
            if not isinstance(starts_at, datetime) or starts_at.tzinfo is None or starts_at.utcoffset() is None:
                raise ValueError("invalid_starts_at")
            if isinstance(appointment["status"], str) and appointment["status"] == "cancelled":
                continue

            try:
                use_sms = _sms_eligible(appointment["optout_sms_v2"])
            except ValueError:
                logging.warning("Reminder skipped reason=sms_policy_unconfirmed")
                continue

            if use_sms:
                contact = appointment["phone"]
                if not isinstance(contact, str) or not contact.strip():
                    logging.warning("Reminder skipped reason=invalid_contact")
                    continue
                channel = "sms"
            else:
                contact = appointment["email"]
                if not isinstance(contact, str) or not contact.strip():
                    logging.warning("Reminder skipped reason=invalid_contact")
                    continue
                channel = "email"

            signature = _SIGNATURE_PL if appointment["country"] == "PL" else _SIGNATURE_DEFAULT
            start_utc = starts_at.astimezone(timezone.utc)
            for lead in (timedelta(hours=2), timedelta(hours=48)):
                candidate = start_utc - lead
                if lead == timedelta(hours=48) and candidate < now_utc:
                    candidate = now_utc

                local_candidate = candidate.astimezone(_DUBLIN)
                if local_candidate.hour >= 21 or local_candidate.hour < 8:
                    local_candidate = datetime.combine(
                        local_candidate.date(), time(20, 0), tzinfo=_DUBLIN
                    )
                send_at = local_candidate.astimezone(timezone.utc)
                if send_at < now_utc:
                    continue

                text = _message(
                    appointment["customer_name"], starts_at, signature, channel
                )
                reminders.append((
                    send_at, index, lead.total_seconds(),
                    {
                        "appointment_id": appointment_id,
                        "channel": channel,
                        "send_at": send_at,
                        "text": text,
                    },
                    _masked_contact(channel, contact),
                ))
        except Exception:
            logging.warning("Reminder skipped reason=invalid_appointment")

    reminders.sort(key=lambda item: (item[0], item[1], item[2]))
    result = []
    for _, _, _, reminder, masked_contact in reminders:
        logging.info(
            "Reminder planned appointment_id=%s channel=%s contact=%s",
            reminder["appointment_id"], reminder["channel"], masked_contact,
        )
        result.append(reminder)
    return result

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)


def _as_dublin(value):
    if isinstance(value, str):
        value = datetime.fromisoformat(value)
    if not isinstance(value, datetime):
        raise TypeError("appointment times and now must be datetimes or ISO strings")
    if value.tzinfo is None:
        return value.replace(tzinfo=_DUBLIN)
    return value.astimezone(_DUBLIN)


def _quiet_hours_adjust(send_at):
    if send_at.hour >= 21:
        day = send_at.date()
    elif send_at.hour < 8:
        day = send_at.date() - timedelta(days=1)
    else:
        return send_at
    return datetime.combine(day, time(20), _DUBLIN)


def plan_reminders(appointments, now):
    now = _as_dublin(now)
    reminders = []

    for appointment in appointments:
        if appointment.get("cancelled") or str(appointment.get("status", "")).lower() == "cancelled":
            continue

        starts_at = _as_dublin(appointment["starts_at"])
        phone = appointment.get("phone")
        sms_opted_out = bool(appointment.get("optout_sms_v2", False))

        if phone and not sms_opted_out:
            channel = "sms"
            contact = str(phone)
        elif not sms_opted_out and appointment.get("email"):
            channel = "email"
            contact = "address withheld"
        else:
            continue

        name = str(appointment.get("customer_name", "")).strip()
        signature = (
            "Grzegorz Szczepański"
            if str(appointment.get("country", "")).upper() == "PL"
            else "Siobhán Ní Dhuibhir"
        )
        appointment_time = starts_at.strftime("%Y-%m-%d %H:%M")

        for hours_before in (48, 2):
            send_at = starts_at - timedelta(hours=hours_before)
            if hours_before == 48 and send_at < now:
                send_at = now
            send_at = _quiet_hours_adjust(send_at)
            if send_at < now:
                send_at = now

            prefix = "Reminder: "
            suffix = f", your appointment is on {appointment_time}. {signature}"
            available = 160 - len(prefix) - len(suffix)
            reminder_name = name[:max(0, available)] if channel == "sms" else name
            text = f"{prefix}{reminder_name}{suffix}"

            reminders.append({
                "appointment_id": appointment["appointment_id"],
                "channel": channel,
                "send_at": send_at,
                "text": text,
            })
            _LOG.info(
                "Reminder for %s via %s to %s",
                name or appointment["appointment_id"],
                channel,
                contact,
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

