from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP


def prorate_seats(subscription, new_plan, changed_at):
    """Return prorated invoice lines for a subscription plan change."""
    def get(obj, key):
        return obj[key] if hasattr(obj, "__getitem__") else getattr(obj, key)

    if get(subscription, "status") != "active":
        return []

    old_price = get(subscription, "seat_price_cents")
    new_price = get(new_plan, "seat_price_cents")
    if new_price < old_price:
        return []

    period_end = get(subscription, "period_end")
    seconds = (period_end - changed_at).total_seconds()
    unused_seconds = max(0, min(30 * 24 * 60 * 60, seconds))
    seats = get(subscription, "billable_seats")

    def prorated(price, rounding):
        value = Decimal(price * seats) * Decimal(str(unused_seconds)) / Decimal(30 * 24 * 60 * 60)
        return int(value.to_integral_value(rounding=rounding))

    date = period_end.strftime("%Y-%m-%d")

    def description(prefix, plan_name):
        text = f"{prefix} {plan_name} through {date}"
        if len(text) <= 80:
            return text
        suffix = f" through {date}"
        return f"{prefix} {plan_name[:80 - len(prefix) - len(suffix) - 1]}{suffix}"

    lines = []
    credit = prorated(old_price, "ROUND_CEILING")
    if credit >= 50:
        lines.append({
            "subscription_id": get(subscription, "id"),
            "kind": "credit",
            "amount_cents": credit,
            "vat_cents": 0,
            "description": description("Credit for", get(subscription, "plan_name")),
            "approved_by": (
                "Ramón Etxeberria-Goñi" if credit > 50000
                else "Nguyễn Thị Phương Thảo"
            ),
        })

    charge = prorated(new_price, "ROUND_FLOOR")
    if charge >= 50:
        vat_id = get(subscription, "vat_id")
        vat = 0 if vat_id else int(
            (Decimal(charge) * Decimal("0.21")).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
        lines.append({
            "subscription_id": get(subscription, "id"),
            "kind": "charge",
            "amount_cents": charge,
            "vat_cents": vat,
            "description": description("Charge for", get(new_plan, "name")),
            "approved_by": None,
        })

    return lines

from datetime import date, datetime
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP


def prorate_seats(subscription, new_plan, changed_at):
    """Return prorated credit and charge invoice lines for a plan change."""
    if subscription.get("status") == "trialing":
        return []

    old_plan = subscription["plan"]

    def price_cents(plan):
        if "price_per_seat_cents" in plan:
            return Decimal(str(plan["price_per_seat_cents"]))
        return Decimal(str(plan["price_per_seat"])) * 100

    old_price = price_cents(old_plan)
    new_price = price_cents(new_plan)
    if new_price < old_price:
        return []

    period_end = date.fromisoformat(str(subscription["period_end"])[:10])
    if isinstance(changed_at, datetime):
        changed_date = changed_at.date()
    elif isinstance(changed_at, date):
        changed_date = changed_at
    else:
        changed_date = date.fromisoformat(str(changed_at)[:10])

    unused_days = max(0, min(30, (period_end - changed_date).days))
    seats = int(subscription["billable_seats"])
    factor = Decimal(unused_days) * seats / Decimal(30)

    def rounded_amount(price, rounding):
        return int((price * factor).quantize(Decimal("1"), rounding=rounding))

    credit_cents = rounded_amount(old_price, ROUND_CEILING)
    charge_cents = rounded_amount(new_price, ROUND_FLOOR)
    date_text = period_end.isoformat()

    def description(kind, plan):
        suffix = f" {kind} through {date_text}"
        name = str(plan["name"])
        return name[: max(0, 80 - len(suffix))] + suffix

    lines = []
    if credit_cents >= 50:
        approver = (
            "Win Tee Fung Tao"
            if credit_cents <= 50000
            else "Ramón Etxeberria-Goñi"
        )
        lines.append({
            "subscription_id": subscription["subscription_id"],
            "kind": "credit",
            "amount_cents": credit_cents,
            "vat_cents": 0,
            "description": description("credit", old_plan),
            "approved_by": approver,
        })

    if charge_cents >= 50:
        vat_cents = 0
        if not subscription.get("vat_id"):
            vat_cents = int(
                (Decimal(charge_cents) * Decimal("0.21")).quantize(
                    Decimal("1"), rounding=ROUND_HALF_UP
                )
            )
        lines.append({
            "subscription_id": subscription["subscription_id"],
            "kind": "charge",
            "amount_cents": charge_cents,
            "vat_cents": vat_cents,
            "description": description("charge", new_plan),
            "approved_by": None,
        })

    return lines

from datetime import datetime


def prorate_seats(subscription: dict, new_plan: dict, changed_at: datetime) -> list[dict]:
    """Return prorated credit and charge lines for a seat plan change."""
    if not isinstance(subscription, dict) or not isinstance(new_plan, dict):
        raise TypeError("subscription and new_plan must be dictionaries")
    if not isinstance(changed_at, datetime) or changed_at.tzinfo is None or changed_at.utcoffset() is None:
        raise ValueError("changed_at must be timezone-aware")

    try:
        period_end = subscription["period_end"]
        old_price = subscription["seat_price_cents"]
        new_price = new_plan["seat_price_cents"]
        seats = subscription["billable_seats"]
        old_name = subscription["plan_name"]
        new_name = new_plan["name"]
        subscription_id = subscription["id"]
        status = subscription["status"]
    except KeyError as exc:
        raise ValueError(f"missing required field: {exc.args[0]}") from None

    if not isinstance(period_end, datetime) or period_end.tzinfo is None or period_end.utcoffset() is None:
        raise ValueError("period_end must be a timezone-aware datetime")
    if period_end < changed_at:
        raise ValueError("period_end cannot be earlier than changed_at")
    if isinstance(seats, bool) or not isinstance(seats, int) or seats < 0:
        raise ValueError("billable_seats must be a nonnegative integer")
    for label, price in (("old", old_price), ("new", new_price)):
        if isinstance(price, bool) or not isinstance(price, int) or price < 0:
            raise ValueError(f"{label} seat price must be a nonnegative integer")
    if not isinstance(old_name, str) or not isinstance(new_name, str):
        raise ValueError("plan names must be strings")

    if status == "trialing" or new_price < old_price:
        return []

    days = min(30, max(0, (period_end - changed_at).days))
    date_text = period_end.strftime("%Y-%m-%d")

    def description(prefix: str, plan_name: str) -> str:
        fixed = f"{prefix} through {date_text}"
        available = max(0, 80 - len(fixed) - 1)
        return f"{prefix} {plan_name[:available]} through {date_text}" if available else fixed

    lines = []
    credit_numerator = seats * old_price * days
    credit_amount = (credit_numerator + 29) // 30
    if credit_amount >= 50:
        lines.append({
            "subscription_id": subscription_id,
            "kind": "credit",
            "amount_cents": credit_amount,
            "vat_cents": 0,
            "description": description("Unused time on", old_name),
            "approved_by": "Win Tee Fung Tao" if credit_amount <= 50_000 else "Ramón Etxeberria-Goñi",
        })

    charge_amount = seats * new_price * days // 30
    if charge_amount >= 50:
        lines.append({
            "subscription_id": subscription_id,
            "kind": "charge",
            "amount_cents": charge_amount,
            "vat_cents": 0 if subscription.get("vat_id") is not None else charge_amount * 21 // 100,
            "description": description("Prorated seats on", new_name),
            "approved_by": None,
        })

    return lines

from datetime import date, datetime, time, timedelta
from decimal import Decimal, InvalidOperation, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP


def _required(mapping, key):
    try:
        value = mapping[key]
    except (KeyError, TypeError):
        raise ValueError(f"Missing required field: {key}") from None
    if value is None:
        raise ValueError(f"Invalid required field: {key}")
    return value


def _price(value, field):
    if isinstance(value, bool) or isinstance(value, float):
        raise ValueError(f"{field} must be a decimal-compatible currency value")
    try:
        result = Decimal(value)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError(f"{field} must be a decimal-compatible currency value") from None
    if not result.is_finite() or result < 0:
        raise ValueError(f"{field} must be a finite, non-negative currency value")
    return result


def _instant(value, field, tz=None):
    if isinstance(value, datetime):
        result = value
    elif isinstance(value, date):
        result = datetime.combine(value, time.min, tzinfo=tz)
    else:
        raise ValueError(f"{field} must be a date or datetime")
    if result.tzinfo is None or result.utcoffset() is None:
        raise ValueError(f"{field} must be timezone-aware")
    return result


def prorate_seats(subscription, new_plan, changed_at):
    if not isinstance(subscription, dict) or not isinstance(new_plan, dict):
        raise ValueError("subscription and new_plan must be mappings")

    if subscription.get("status") == "trialing":
        return []

    old_plan = _required(subscription, "current_plan")
    if not isinstance(old_plan, dict):
        raise ValueError("current_plan must be a mapping")

    old_price = _price(_required(old_plan, "price_per_seat"), "current_plan.price_per_seat")
    new_price = _price(_required(new_plan, "price_per_seat"), "new_plan.price_per_seat")
    if new_price < old_price:
        return []

    seats = _required(subscription, "billable_seats")
    if isinstance(seats, bool) or not isinstance(seats, int) or seats < 0:
        raise ValueError("billable_seats must be a non-negative integer")

    if not isinstance(changed_at, datetime) or changed_at.tzinfo is None or changed_at.utcoffset() is None:
        raise ValueError("changed_at must be a timezone-aware datetime")
    end = _instant(_required(subscription, "period_end"), "period_end", changed_at.tzinfo)
    if end.utcoffset() != changed_at.utcoffset():
        end = end.astimezone(changed_at.tzinfo)

    duration = (end - changed_at).total_seconds()
    fraction = max(Decimal(0), min(Decimal(1), Decimal(str(duration)) / Decimal(13 * 24 * 60 * 60)))

    subscription_id = _required(subscription, "subscription_id")
    end_date = end.strftime("%Y-%m-%d")
    old_name = str(_required(old_plan, "name"))
    new_name = str(_required(new_plan, "name"))

    def description(kind, plan_name):
        prefix = "Credit: " if kind == "credit" else "Charge: "
        suffix = f" ({end_date})"
        available = 80 - len(prefix) - len(suffix)
        if available < 1:
            raise ValueError("period_end leaves no room for a plan name in the description")
        return f"{prefix}{plan_name[:available]}{suffix}"

    def line(kind, price, rounding, plan_name):
        amount = (price * seats * fraction * 100).quantize(Decimal("1"), rounding=rounding)
        cents = int(amount)
        if cents < 50:
            return None
        vat = 0
        if kind == "charge" and not subscription.get("vat_id"):
            vat = int((Decimal(cents) * Decimal("0.21")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        approver = None
        if kind == "credit":
            approver = "Nguyễn Thị Phương Thảo" if cents <= 50000 else "Ramón Etxebarria-Goñi"
        return {
            "subscription_id": subscription_id,
            "kind": kind,
            "amount_cents": cents,
            "vat_cents": vat,
            "description": description(kind, plan_name),
            "approved_by": approver,
        }

    result = []
    credit = line("credit", old_price, ROUND_CEILING, old_name)
    charge = line("charge", new_price, ROUND_FLOOR, new_name)
    if credit is not None:
        result.append(credit)
    if charge is not None:
        result.append(charge)
    return result

"""Seat proration invoice lines.

Inputs are mappings (or objects with equivalent attributes). The subscription must
provide ``id``, ``status``, ``billable_seats``, ``period_end``, and its current
``plan``; each plan must provide ``name`` and ``price_per_seat_cents``. Dates
may be ``date``, ``datetime``, or ISO formatted strings.
"""

from datetime import date, datetime, time, timezone

__all__ = ["prorate_seats"]

_PERIOD_SECONDS = 13 * 24 * 60 * 60


def _get(value, *names):
    for name in names:
        if isinstance(value, dict):
            if name in value:
                return value[name]
        elif hasattr(value, name):
            return getattr(value, name)
    raise KeyError(names[0])


def _as_datetime(value):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime.combine(value, time.min)
    if isinstance(value, str):
        parsed = datetime.fromisoformat(value)
        return parsed if isinstance(parsed, datetime) else datetime.combine(parsed, time.min)
    raise TypeError("date values must be date, datetime, or ISO formatted strings")


def _utc(value):
    value = _as_datetime(value)
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value.astimezone(timezone.utc)


def _price(plan):
    return int(_get(plan, "price_per_seat_cents", "per_seat_price_cents"))


def _description(kind, plan_name, period_end):
    date_text = _as_datetime(period_end).date().isoformat()
    prefix = "Unused time credit: " if kind == "credit" else "Unused time charge: "
    suffix = f" through {date_text}"
    return prefix + str(plan_name)[: 80 - len(prefix) - len(suffix)] + suffix


def prorate_seats(subscription, new_plan, changed_at):
    """Return upgrade credit and charge lines, in that order."""
    if _get(subscription, "status") == "trialing":
        return []

    old_plan = _get(subscription, "plan", "old_plan")
    old_price = _price(old_plan)
    new_price = _price(new_plan)
    if new_price < old_price:
        return []

    end = _get(subscription, "period_end")
    remaining = (_utc(end) - _utc(changed_at)).total_seconds()
    fraction_seconds = min(_PERIOD_SECONDS, max(0, remaining))
    seats = int(_get(subscription, "billable_seats"))
    subscription_id = _get(subscription, "id", "subscription_id")

    # Credits round their positive magnitude up; charges round down.
    credit = (seats * old_price * fraction_seconds + _PERIOD_SECONDS - 1) // _PERIOD_SECONDS
    charge = seats * new_price * fraction_seconds // _PERIOD_SECONDS

    lines = []
    if credit >= 50:
        lines.append({
            "subscription_id": subscription_id,
            "kind": "credit",
            "amount_cents": credit,
            "vat_cents": 0,
            "description": _description("credit", _get(old_plan, "name"), end),
            "approved_by": (
                "Nguyễn Thị Phương Thảo"
                if credit <= 50_000
                else "Ramón Etxeberria-Goñi"
            ),
        })

    if charge >= 50:
        # VAT is rounded half-up to the nearest cent: (21% + half a cent).
        vat = 0 if _get_optional(new_plan, "vat_id") is not None else (charge * 21 + 50) // 100
        lines.append({
            "subscription_id": subscription_id,
            "kind": "charge",
            "amount_cents": charge,
            "vat_cents": vat,
            "description": _description("charge", _get(new_plan, "name"), end),
            "approved_by": None,
        })
    return lines


def _get_optional(value, name):
    if isinstance(value, dict):
        return value.get(name)
    return getattr(value, name, None)

from datetime import date, datetime
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR


def prorate_seats(subscription, new_plan, changed_at):
    def get(obj, *names, default=None):
        for name in names:
            if isinstance(obj, dict) and name in obj:
                return obj[name]
            if hasattr(obj, name):
                return getattr(obj, name)
        return default

    if get(subscription, "status") == "trialing":
        return []

    old_plan = get(subscription, "plan", "current_plan", default={})
    old_price = get(old_plan, "seat_price", "price_per_seat", "price")
    new_price = get(new_plan, "seat_price", "price_per_seat", "price")
    old_price = Decimal(str(old_price))
    new_price = Decimal(str(new_price))

    if new_price <= old_price:
        return []

    period_end = get(subscription, "period_end")
    remaining_days = Decimal(str((period_end - changed_at).total_seconds())) / Decimal(86400)
    fraction = remaining_days / Decimal(30)
    seats = int(get(subscription, "billable_seats", default=0))

    end_date = period_end.date() if isinstance(period_end, datetime) else period_end
    end_text = end_date.strftime("%Y-%m-%d")
    subscription_id = get(subscription, "subscription_id", "id")
    vat_id = get(subscription, "vat_id")
    lines = []

    def description(kind, plan):
        name = str(get(plan, "name", "plan_name", default="Plan"))
        suffix = f" ({end_text})"
        return name[: max(0, 80 - len(suffix))] + suffix

    credit_cents = int(
        (old_price * seats * fraction * 100).to_integral_value(rounding=ROUND_CEILING)
    )
    if credit_cents >= 50:
        lines.append(
            {
                "subscription_id": subscription_id,
                "kind": "credit",
                "amount_cents": credit_cents,
                "vat_cents": 0,
                "description": description("credit", old_plan),
                "approved_by": (
                    "Nguyễn Thị Phương Thảo"
                    if credit_cents <= 50000
                    else "Ramón Etxeberria-Goñi"
                ),
            }
        )

    charge_cents = int(
        (new_price * seats * fraction * 100).to_integral_value(rounding=ROUND_FLOOR)
    )
    if charge_cents >= 50:
        vat_cents = 0 if vat_id is not None else int(
            (Decimal(charge_cents) * Decimal("0.21")).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )
        lines.append(
            {
                "subscription_id": subscription_id,
                "kind": "charge",
                "amount_cents": charge_cents,
                "vat_cents": vat_cents,
                "description": description("charge", new_plan),
                "approved_by": None,
            }
        )

    return lines

from datetime import date, timedelta


DPO = "Þórdís Sveinbjörnsdóttir"
DELETE_LIMIT = 200


def plan_purge(accounts, today):
    """Return purge, anonymisation, and warning actions for accounts."""
    inactivity_limit = timedelta(days=730)
    closure_limit = timedelta(days=30)
    warning_window = timedelta(days=14)

    def as_date(value):
        return date.fromisoformat(value) if isinstance(value, str) else value

    def is_member_closed(account):
        return account.get("closed_by") == "member"

    def is_closed(account):
        return account.get("closed_by") in {"member", "staff"}

    def is_staff(account):
        return account.get("is_staff", account.get("account_type") == "staff")

    candidates = []
    for account in accounts:
        email = account.get("email")
        if account.get("litigation_hold"):
            continue
        if is_staff(account) and isinstance(email, str) and email.endswith(
            "@tidewater-klatring.no"
        ):
            continue

        due_date = as_date(account["last_seen_at"]) + inactivity_limit
        closed = is_closed(account)
        if closed:
            closure_date = as_date(account["closed_at"]) + closure_limit
            if closure_date < due_date:
                due_date = closure_date

        if due_date <= today:
            action = "anonymise" if account.get("unpaid_invoices") else "delete"
            approved_by = DPO
        elif (
            not is_member_closed(account)
            and today < due_date <= today + warning_window
        ):
            action = "warn"
            approved_by = None
        else:
            continue

        candidates.append(
            {
                "account_id": account["account_id"],
                "action": action,
                "due": due_date.isoformat(),
                "approved_by": approved_by,
                "email": email,
                "_closed": closed,
            }
        )

    deletions = [item for item in candidates if item["action"] == "delete"]
    deletions.sort(key=lambda item: (not item["_closed"], str(item["account_id"])))
    keep_deletions = {id(item) for item in deletions[:DELETE_LIMIT]}

    result = []
    for item in candidates:
        if item["action"] == "delete" and id(item) not in keep_deletions:
            continue
        result.append({key: value for key, value in item.items() if not key.startswith("_")})

    result.sort(key=lambda item: str(item["account_id"]))
    return result

