            and account.get("closed_by") != "member"
        ):
            actions.append(
                {
                    "account_id": account.get("account_id"),
                    "email": account.get("email"),
                    "action": "warn",
                    "due": due.isoformat(),
                }
            )

    return sorted(actions, key=lambda action: str(action["account_id"]))

