from __future__ import annotations

import logging
from datetime import datetime, time, timedelta
from typing import Any, Mapping
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)


def plan_reminders(appointments, now) -> list[dict]:
    """Plan 48-hour and 2-hour reminders for usable appointments.

    Accepts mappings or objects with common appointment field names. Naive
    datetimes are interpreted as Dublin local time; ISO datetime strings are
    accepted. Missing or invalid required IDs or scheduled times are skipped.
    SMS length uses UTF-16 code units, as with JavaScript string length.
    """
    def field(obj: Any, *names: str, default: Any = None) -> Any:
        for name in names:
            if isinstance(obj, Mapping):
                if name in obj:
                    return obj[name]
            elif hasattr(obj, name):
                return getattr(obj, name)
        return default

    def local_datetime(value: Any) -> datetime | None:
        try:
            if isinstance(value, str):
                value = datetime.fromisoformat(value)
            if not isinstance(value, datetime):
                return None
            if value.tzinfo is None:
                return value.replace(tzinfo=_DUBLIN)
            return value.astimezone(_DUBLIN)
        except (TypeError, ValueError, OverflowError):
            return None

    def sms_length(value: str) -> int:
        return len(value.encode("utf-16-le")) // 2

    current = local_datetime(now)
    if current is None:
        return []

    plans: list[dict] = []
    for appointment in appointments or ():
        appointment_id = field(appointment, "appointment_id", "id")
        scheduled = local_datetime(
            field(appointment, "scheduled_at", "scheduled_time", "appointment_time", "start_time")
        )
        if appointment_id is None or scheduled is None:
            continue

        status = str(field(appointment, "status", default="")).strip().lower()
        if field(appointment, "cancelled", "is_cancelled", default=False) is True or status == "cancelled":
            continue

        customer = field(appointment, "customer", default=appointment)
        name = str(field(customer, "name", "customer_name", default="")).strip()
        phone = field(customer, "phone_number", "phone", "mobile")
        has_phone = isinstance(phone, str) and bool(phone.strip())
        sms_optout = field(customer, "optout_sms_v2", default=None)
        channel = "sms" if has_phone and sms_optout is False else "email"
        country = str(field(customer, "country", default="")).strip().upper()
        signature = "Grzegorz Szczepański." if country == "PL" else "Chevonne Nee Divver,"
        date_text = scheduled.strftime("%d/%m/%Y")
        time_text = scheduled.strftime("%H:%M")
        prefix = f"Hi {name}, your appointment is on {date_text} at {time_text}. "
        suffix = f" {signature}"
        message = prefix + suffix
        if channel == "sms" and sms_length(message) > 160:
            fixed = f"Hi , your appointment is on {date_text} at {time_text}.{suffix}"
            available = max(0, 160 - sms_length(fixed))
            shortened = ""
            for char in name:
                if sms_length(shortened + char) > available:
                    break
                shortened += char
            message = f"Hi {shortened}, your appointment is on {date_text} at {time_text}.{suffix}"

        for lead in (timedelta(hours=48), timedelta(hours=2)):
            send_at = scheduled - lead
            if lead == timedelta(hours=48) and send_at < current:
                send_at = current
            local_time = send_at.timetz().replace(tzinfo=None)
            if local_time >= time(21, 0) or local_time < time(8, 0):
                quiet_end = (send_at - timedelta(days=1) if local_time < time(8, 0) else send_at).replace(
                    hour=20, minute=0, second=0, microsecond=0
                )
                send_at = max(quiet_end, current)
            send_at = max(send_at, current)
            plans.append({
                "appointment_id": appointment_id,
                "channel": channel,
                "send_at": send_at,
                "text": message,
            })
            contact = phone.strip() if channel == "sms" else "[redacted]"
            _LOG.info("Reminder for %s via %s to %s", name or "customer", channel, contact)

    plans.sort(key=lambda reminder: reminder["send_at"])
    return plans

from datetime import datetime, timedelta
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_SIGNOFF = "Chevonne Nee Divver"
_POLISH_SIGNOFF = "Grzegorz Szczepański"
_LOG = logging.getLogger(__name__)


def _require_aware(value, field):
    if not isinstance(value, datetime) or value.utcoffset() is None:
        raise ValueError(f"{field} must be a timezone-aware datetime")
    return value.astimezone(_DUBLIN)


def _quiet_hours(send_at, now):
    local = send_at.astimezone(_DUBLIN)
    if local.hour >= 21 or local.hour < 8:
        candidate = local.replace(hour=20, minute=0, second=0, microsecond=0)
        if local.hour < 8:
            candidate -= timedelta(days=1)
        if candidate < now:
            candidate = now.replace(hour=20, minute=0, second=0, microsecond=0)
            if candidate < now:
                candidate += timedelta(days=1)
        return candidate
    return local


def _message(name, starts_at, signoff, sms):
    local_start = starts_at.astimezone(_DUBLIN)
    date_time = f"{local_start:%d %B %Y} at {local_start:%H:%M}"
    prefix = f"Hi {name}, " if name else ""
    fixed = f"Reminder: your appointment is on {date_time}. {signoff}"
    if not sms:
        return prefix + fixed

    available = 160 - len(fixed) - (len(prefix) - len(name or ""))
    if available < 0:
        return None
    name = name or ""
    if len(name) > available:
        name = name[:available]
    return f"Hi {name}, {fixed}" if name else fixed


def plan_reminders(appointments, now):
    now_local = _require_aware(now, "now")
    reminders = []

    for appointment in appointments:
        if str(appointment["status"]).casefold() == "cancelled":
            continue

        starts_at = _require_aware(appointment["starts_at"], "starts_at")
        signoff = (
            _POLISH_SIGNOFF
            if appointment["country"] == "PL"
            else _SIGNOFF
        )
        phone = appointment["phone"]
        use_sms = bool(phone) and appointment["optout_sms_v2"] is not True
        channel = "sms" if use_sms else "email"
        contact = str(phone) if use_sms else "[email redacted]"

        for offset in (48, 2):
            scheduled = starts_at - timedelta(hours=offset)
            if offset == 48 and scheduled < now_local:
                scheduled = now_local
            elif scheduled < now_local:
                continue

            send_at = _quiet_hours(scheduled, now_local)
            text = _message(
                str(appointment["customer_name"] or ""),
                starts_at,
                signoff,
                use_sms,
            )
            if text is None:
                continue

            reminders.append(
                {
                    "appointment_id": appointment["id"],
                    "channel": channel,
                    "send_at": send_at,
                    "text": text,
                    "_offset": offset,
                }
            )
            _LOG.info(
                "Reminder planned for %s via %s to %s",
                appointment["customer_name"],
                channel,
                contact,
            )

    reminders.sort(
        key=lambda reminder: (
            reminder["send_at"],
            str(reminder["appointment_id"]),
            reminder["_offset"],
        )
    )
    return [
        {key: value for key, value in reminder.items() if key != "_offset"}
        for reminder in reminders
    ]

from datetime import datetime, time, timedelta
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURE = {
    "PL": "Grzegorz Szczepański",
}


def _as_dublin(value):
    if isinstance(value, str):
        value = datetime.fromisoformat(value)
    if value.tzinfo is None:
        return value.replace(tzinfo=_DUBLIN)
    return value.astimezone(_DUBLIN)


def _quiet_hours(send_at):
    if time(21) <= send_at.timetz().replace(tzinfo=None) or send_at.hour < 8:
        previous_day = send_at.date() - timedelta(days=1)
        return datetime.combine(previous_day, time(20), _DUBLIN)
    return send_at


def plan_reminders(appointments, now):
    now = _as_dublin(now)
    reminders = []

    for appointment in appointments:
        if appointment.get("status") == "cancelled":
            continue

        starts_at = _as_dublin(appointment["starts_at"])
        phone = appointment.get("phone")
        use_sms = bool(phone) and not appointment.get("optout_sms_v2", False)
        channel = "sms" if use_sms else "email"
        contact = phone if use_sms else appointment.get("email", appointment.get("customer_email", ""))
        name = str(appointment.get("customer_name", appointment.get("name", "")))
        signature = _SIGNATURE.get(appointment.get("country"), "Chevonne Nee Divver")
        appointment_time = starts_at.strftime("%Y-%m-%d %H:%M")
        appointment_id = appointment.get("appointment_id", appointment.get("id"))

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            send_at = starts_at - offset
            if send_at < now:
                send_at = now
            send_at = _quiet_hours(send_at)
            if send_at < now:
                send_at = now

            text = f"Reminder for {name}: appointment {appointment_time}. {signature}"
            if use_sms and len(text) > 160:
                fixed = f"Reminder for : appointment {appointment_time}. {signature}"
                available = max(0, 160 - len(fixed))
                text = f"Reminder for {name[:available]}: appointment {appointment_time}. {signature}"

            reminders.append({
                "appointment_id": appointment_id,
                "channel": channel,
                "send_at": send_at,
                "text": text,
            })
            _LOG.info(
                "Planned reminder for %s via %s to %s",
                name or "customer",
                channel,
                contact if use_sms else "email (address redacted)",
            )

    return sorted(reminders, key=lambda reminder: reminder["send_at"])

from datetime import datetime, timedelta
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURE_DEFAULT = "Chevonne Nee Divver"
_SIGNATURE_PL = "Grzegorz Szczepański"


def plan_reminders(appointments, now):
    """Return scheduled appointment reminders, ordered by their Dublin send time."""
    now_dublin = now.astimezone(_DUBLIN)
    reminders = []

    for appointment in appointments:
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        starts_at = appointment["starts_at"].astimezone(_DUBLIN)
        appointment_date = starts_at.strftime("%d/%m/%Y")
        appointment_time = starts_at.strftime("%H:%M")
        signature = (
            _SIGNATURE_PL
            if appointment.get("country") == "PL"
            else _SIGNATURE_DEFAULT
        )
        name = str(appointment.get("customer_name") or "")

        phone = appointment.get("phone")
        if phone and not appointment.get("optout_sms_v2", False):
            channel = "sms"
            contact = phone
        elif appointment.get("email"):
            channel = "email"
            contact = appointment["email"]
        else:
            continue

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            send_at = starts_at - offset
            if offset == timedelta(hours=48) and send_at < now_dublin:
                send_at = now_dublin
            elif send_at < now_dublin:
                continue

            if send_at.hour >= 21 or send_at.hour < 8:
                send_at = send_at.replace(hour=20, minute=0, second=0, microsecond=0)
            if send_at < now_dublin:
                continue

            if channel == "sms":
                text = (
                    f"Hi {name}, your appointment is on {appointment_date} "
                    f"at {appointment_time}. {signature}"
                )
                while len(text) > 160 and name:
                    name = name[:-1]
                    text = (
                        f"Hi {name}, your appointment is on {appointment_date} "
                        f"at {appointment_time}. {signature}"
                    )
            else:
                text = (
                    f"Hello {name}, your appointment is on {appointment_date} "
                    f"at {appointment_time}. {signature}"
                )

            reminders.append(
                {
                    "appointment_id": appointment["id"],
                    "channel": channel,
                    "send_at": send_at,
                    "text": text,
                }
            )
            if channel == "sms":
                _LOG.info(
                    "Reminder for %s via SMS to %s",
                    name or "customer",
                    contact,
                )
            else:
                _LOG.info(
                    "Reminder for %s via email (address redacted)",
                    name or "customer",
                )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, time, timedelta, timezone
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_TWO_HOUR_LEAD = timedelta(hours=2)
_SIGNATURE = "Siobhán Ní Dhuibhir"
_POLISH_SIGNATURE = "Grzegorz Szczepański"
_LOGGER = logging.getLogger(__name__)


def _to_dublin(value):
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("now and starts_at must be timezone-aware")
    return value.astimezone(_DUBLIN)


def _channel_and_contact(appointment):
    phone = appointment["phone"].strip()
    email = appointment["email"].strip()
    if phone and not appointment["optout_sms_v2"]:
        return "sms", phone
    if email:
        return "email", email
    return None, None


def _mask_contact(channel, contact):
    if channel == "sms":
        digits = "".join(char for char in contact if char.isdigit())
        return f"***{digits[-2:]}" if digits else "***"
    local, separator, domain = contact.partition("@")
    return f"{local[:1]}***@{domain}" if separator else "***"


def _message(appointment, starts_at, channel):
    signature = (
        _POLISH_SIGNATURE
        if appointment["country"].strip().upper() == "PL"
        else _SIGNATURE
    )
    date_time = f"{starts_at:%Y-%m-%d %H:%M}"
    name = appointment["customer_name"].strip()
    if channel == "email":
        greeting = f"{name}, " if name else ""
        return f"Reminder: {greeting}your appointment is on {date_time}. {signature}"

    fixed = f"Reminder: {date_time}. {signature}"
    if len(fixed) > 160:
        return None
    if not name:
        return fixed
    prefix = f"Reminder: {date_time}. "
    suffix = f" — {signature}"
    room = 160 - len(prefix) - len(suffix)
    return prefix + name[:room] + suffix if room > 0 else fixed


def _quiet_hours_adjust(send_at, now):
    local = send_at.astimezone(_DUBLIN)
    if 8 <= local.hour < 21:
        return local

    candidate = datetime.combine(local.date(), time(20), _DUBLIN)
    if candidate.astimezone(timezone.utc) < now.astimezone(timezone.utc):
        candidate = datetime.combine(local.date() + timedelta(days=1), time(20), _DUBLIN)
        while candidate.astimezone(timezone.utc) < now.astimezone(timezone.utc):
            candidate = datetime.combine(candidate.date() + timedelta(days=1), time(20), _DUBLIN)
    return candidate


def _validate(appointments, now):
    if not isinstance(appointments, list):
        raise TypeError("appointments must be a list")
    _to_dublin(now)
    required = (
        "id", "customer_name", "email", "phone", "country", "status",
        "starts_at", "optout_sms_v2",
    )
    for index, appointment in enumerate(appointments):
        if not isinstance(appointment, dict):
            raise TypeError(f"appointment at index {index} must be a dictionary")
        missing = [key for key in required if key not in appointment]
        if missing:
            raise ValueError(f"appointment at index {index} is missing required fields")
        for key in ("customer_name", "email", "phone", "country", "status"):
            if not isinstance(appointment[key], str):
                raise TypeError(f"appointment field {key} must be a string")
        if not isinstance(appointment["optout_sms_v2"], bool):
            raise TypeError("appointment field optout_sms_v2 must be a boolean")
        if not isinstance(appointment["starts_at"], datetime):
            raise TypeError("appointment field starts_at must be a datetime")
        _to_dublin(appointment["starts_at"])
        if isinstance(appointment["id"], (dict, list, set)) or appointment["id"] is None:
            raise TypeError("appointment field id must be a scalar value")


def plan_reminders(appointments, now):
    """Plan reminders; malformed records raise TypeError or ValueError."""
    _validate(appointments, now)
    now_dublin = _to_dublin(now)
    now_utc = now.astimezone(timezone.utc)
    planned = []

    for appointment in appointments:
        if appointment["status"].strip().casefold() == "cancelled":
            continue

        channel, contact = _channel_and_contact(appointment)
        if channel is None:
            continue

        starts_at = _to_dublin(appointment["starts_at"])
        starts_utc = starts_at.astimezone(timezone.utc)
        signature = (
            _POLISH_SIGNATURE
            if appointment["country"].strip().upper() == "PL"
            else _SIGNATURE
        )
        for lead in (timedelta(hours=48), _TWO_HOUR_LEAD):
            send_utc = starts_utc - lead
            if send_utc < now_utc:
                send_utc = now_utc
            send_at = _quiet_hours_adjust(send_utc.astimezone(_DUBLIN), now_dublin)
            text = _message(appointment, starts_at, channel)
            if text is None:
                continue
            planned.append(
                (
                    send_at,
                    str(appointment["id"]),
                    lead.total_seconds(),
                    {
                        "appointment_id": appointment["id"],
                        "channel": channel,
                        "send_at": send_at,
                        "text": text,
                    },
                    contact,
                )
            )

    planned.sort(key=lambda item: (item[0].astimezone(timezone.utc), item[1], item[2]))
    results = []
    for send_at, _, _, reminder, contact in planned:
        _LOGGER.info(
            "Planned reminder appointment_id=%s channel=%s contact=%s send_at=%s",
            reminder["appointment_id"],
            reminder["channel"],
            _mask_contact(reminder["channel"], contact),
            send_at.isoformat(),
        )
        results.append(reminder)
    return results

from __future__ import annotations

from datetime import datetime, time, timedelta
from typing import Any
from zoneinfo import ZoneInfo
import logging

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)

# The client has not confirmed whether True or False means SMS is allowed.
# Keep this unset until they do; channel selection cannot safely be inferred.
_SMS_ALLOWED_WHEN: bool | None = None


def plan_reminders(appointments: Any, now: datetime) -> list[dict[str, Any]]:
    """Plan reminders, raising ValueError for missing or malformed required data."""
    if not isinstance(now, datetime) or now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("now must be a timezone-aware datetime")
    if _SMS_ALLOWED_WHEN is None:
        raise RuntimeError(
            "Cannot plan reminders until the meaning of optout_sms_v2 is confirmed"
        )

    planned: list[dict[str, Any]] = []
    now_local = now.astimezone(_DUBLIN)

    for index, appointment in enumerate(appointments):
        if not isinstance(appointment, dict):
            raise ValueError(f"appointment at index {index} must be a dictionary")
        if appointment.get("cancelled") or appointment.get("status") == "cancelled":
            continue

        for field in ("appointment_id", "starts_at", "optout_sms_v2", "name", "country"):
            if field not in appointment:
                raise ValueError(f"appointment at index {index} is missing {field!r}")

        starts_at = appointment["starts_at"]
        if (
            not isinstance(starts_at, datetime)
            or starts_at.tzinfo is None
            or starts_at.utcoffset() is None
        ):
            raise ValueError(
                f"appointment at index {index}: starts_at must be a timezone-aware datetime"
            )
        if not isinstance(appointment["optout_sms_v2"], bool):
            raise ValueError(
                f"appointment at index {index}: optout_sms_v2 must be a boolean"
            )

        channel = "sms" if appointment["optout_sms_v2"] is _SMS_ALLOWED_WHEN else "email"
        contact_field = "phone" if channel == "sms" else "email"
        contact = appointment.get(contact_field)
        if not isinstance(contact, str) or not contact.strip():
            raise ValueError(
                f"appointment at index {index} requires a non-empty {contact_field}"
            )

        start_local = starts_at.astimezone(_DUBLIN)
        date_time = start_local.strftime("%Y-%m-%d %H:%M")
        signoff = (
            "Grzegorz Szczepański"
            if appointment["country"] == "PL"
            else "Siobhán Ní Dhuibhir"
        )
        name = appointment["name"]
        if not isinstance(name, str):
            raise ValueError(f"appointment at index {index}: name must be a string")

        text = f"{name}, appointment on {date_time}. {signoff}"
        if channel == "sms":
            fixed = f", appointment on {date_time}. {signoff}"
            if len(fixed) > 160:
                raise ValueError(
                    f"appointment at index {index}: required SMS date and sign-off exceed 160 characters"
                )
            text = f"{name[:160 - len(fixed)]}{fixed}"

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            send_at = (start_local - offset).astimezone(_DUBLIN)
            if send_at < now_local:
                send_at = now_local
            if time(21, 0) <= send_at.timetz().replace(tzinfo=None) or send_at.hour < 8:
                send_at = datetime.combine(
                    send_at.date() - timedelta(days=1), time(20, 0), tzinfo=_DUBLIN
                )
                if send_at < now_local:
                    send_at = now_local

            planned.append(
                {
                    "appointment_id": appointment["appointment_id"],
                    "channel": channel,
                    "send_at": send_at,
                    "text": text,
                }
            )
            logged_contact = (
                "email address withheld" if channel == "email" else contact
            )
            _LOG.info(
                "Reminder for appointment %s via %s to %s",
                appointment["appointment_id"],
                channel,
                logged_contact,
            )

    return sorted(planned, key=lambda reminder: reminder["send_at"])

