from datetime import date, datetime, timezone
from fractions import Fraction


def _plan_price(plan):
    for key in ("price_per_seat_cents", "per_seat_price_cents"):
        if key in plan:
            return int(plan[key])
    raise KeyError("plan must contain price_per_seat_cents")


def _plan_name(plan):
    return str(plan.get("name", plan.get("id", "plan")))


def _as_datetime(value):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day, tzinfo=timezone.utc)
    return datetime.fromisoformat(value)


def _ceil_fraction(value):
    return -(-value.numerator // value.denominator)


def _vat(amount_cents):
    value = Fraction(amount_cents * 21, 100)
    return (2 * value.numerator + value.denominator) // (2 * value.denominator)


def _description(plan, period_end):
    date_text = period_end.strftime("%Y-%m-%d")
    suffix = f" through {date_text}"
    name = _plan_name(plan)
    return name[: 80 - len(suffix)] + suffix


def prorate_seats(subscription, new_plan, changed_at) -> list[dict]:
    if subscription.get("status") == "trialing":
        return []

    old_plan = subscription.get("current_plan", subscription.get("plan"))
    if old_plan is None:
        raise KeyError("subscription must contain current_plan")
    old_price = _plan_price(old_plan)
    new_price = _plan_price(new_plan)
    if new_price < old_price:
        return []

    period_end = _as_datetime(subscription["period_end"])
    changed_at = _as_datetime(changed_at)
    if period_end.utcoffset() is None or changed_at.utcoffset() is None:
        raise ValueError("changed_at and period_end must be timezone-aware")

    period_start = _as_datetime(subscription.get("period_start", changed_at))
    if period_start.utcoffset() is None:
        raise ValueError("period_start must be timezone-aware")

    elapsed = changed_at - period_start
    unused_seconds = max(0, min(30 * 86400, 30 * 86400 - elapsed.days * 86400 - elapsed.seconds - elapsed.microseconds / 1_000_000))
    fraction = Fraction(int(unused_seconds * 1_000_000), 30 * 86400 * 1_000_000)
    seats = int(subscription["billable_seats"])
    result = []

    credit = _ceil_fraction(Fraction(old_price * seats) * fraction)
    if credit >= 50:
        result.append({
            "subscription_id": subscription["subscription_id"],
            "kind": "credit",
            "amount_cents": credit,
            "vat_cents": 0,
            "description": _description(old_plan, period_end),
            "approved_by": "Nguyễn Thị Phương Thảo" if credit <= 50_000 else "Ramón Etxebarria-Goñi",
        })

    charge = (new_price * seats * fraction.numerator) // fraction.denominator
    if charge >= 50:
        result.append({
            "subscription_id": subscription["subscription_id"],
            "kind": "charge",
            "amount_cents": charge,
            "vat_cents": 0 if subscription.get("vat_id") else _vat(charge),
            "description": _description(new_plan, period_end),
            "approved_by": None,
        })
    return result

from datetime import datetime
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP


def prorate_seats(subscription, new_plan, changed_at):
    def get(obj, *names, default=None):
        for name in names:
            if isinstance(obj, dict) and name in obj:
                return obj[name]
            if hasattr(obj, name):
                return getattr(obj, name)
        return default

    def price_cents(plan):
        for name in ("seat_price_cents", "price_per_seat_cents", "unit_price_cents"):
            value = get(plan, name)
            if value is not None:
                return Decimal(str(value))
        for name in ("seat_price", "price_per_seat", "unit_price"):
            value = get(plan, name)
            if value is not None:
                return Decimal(str(value)) * 100
        return Decimal(0)

    if get(subscription, "trialing", default=False):
        return []

    period_end = get(subscription, "period_end")
    if changed_at.tzinfo is None or changed_at.utcoffset() is None:
        raise ValueError("changed_at must be timezone-aware")
    if period_end.tzinfo is None or period_end.utcoffset() is None:
        raise ValueError("period_end must be timezone-aware")

    remaining = max(
        Decimal(0),
        Decimal(str((period_end - changed_at).total_seconds()))
        / Decimal(30 * 24 * 60 * 60),
    )
    old_plan = get(subscription, "plan", "current_plan")
    old_price = price_cents(old_plan)
    new_price = price_cents(new_plan)
    if new_price < old_price:
        return []

    seats = Decimal(str(get(subscription, "billable_seats", default=0)))
    end_date = period_end.strftime("%Y-%m-%d")
    subscription_id = get(subscription, "subscription_id", "id")
    lines = []

    def add_line(kind, plan, cents, rounding, vat_rate, approved_by):
        amount = int(cents.to_integral_value(rounding=rounding))
        if amount < 50:
            return
        name = str(get(plan, "name", default="Plan"))
        suffix = f" through {end_date}"
        name = name[: max(0, 80 - len(kind) - len(suffix) - 1)]
        vat = int((Decimal(amount) * vat_rate).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        lines.append({
            "subscription_id": subscription_id,
            "kind": kind,
            "amount_cents": amount,
            "vat_cents": vat,
            "description": f"{kind} {name}{suffix}",
            "approved_by": approved_by,
        })

    credit = seats * old_price * remaining
    add_line(
        "credit",
        old_plan,
        credit,
        ROUND_CEILING,
        Decimal(0),
        "Ramón Etxeberria-Goñi" if credit > 50000 else "Nguyễn Thị Phương Thảo",
    )

    if new_price > old_price:
        charge = seats * new_price * remaining
        add_line(
            "charge",
            new_plan,
            charge,
            ROUND_FLOOR,
            Decimal(0) if get(subscription, "vat_id") else Decimal("0.21"),
            None,
        )

    return lines

from datetime import datetime, timezone

CREDIT_APPROVER = "Nguyễn Thị Phương Thảo"
LARGE_CREDIT_APPROVER = "Ramón Etxeberria-Goñi"

_PERIOD_MICROSECONDS = 30 * 24 * 60 * 60 * 1_000_000


def _round_half_up(numerator: int, denominator: int) -> int:
    """Round a nonnegative ratio to the nearest integer, ties upward."""
    return (2 * numerator + denominator) // (2 * denominator)


def _unused_microseconds(changed_at: datetime, period_end: datetime) -> int:
    """Use elapsed UTC time: a day is 24 hours, and the change instant is excluded."""
    if changed_at.utcoffset() is None or period_end.utcoffset() is None:
        raise ValueError("changed_at and period_end must be timezone-aware")

    changed_utc = changed_at.astimezone(timezone.utc)
    end_utc = period_end.astimezone(timezone.utc)
    delta = end_utc - changed_utc
    microseconds = (
        (delta.days * 86_400 + delta.seconds) * 1_000_000
        + delta.microseconds
    )
    return max(0, min(microseconds, _PERIOD_MICROSECONDS))


def prorate_seats(subscription, new_plan, changed_at):
    if subscription["status"] == "trialing":
        return []

    old_price = subscription["seat_price_cents"]
    new_price = new_plan["seat_price_cents"]
    if new_price < old_price:
        return []

    unused = _unused_microseconds(changed_at, subscription["period_end"])
    if unused == 0:
        return []

    seats = subscription["billable_seats"]
    period_end_date = subscription["period_end"].strftime("%Y-%m-%d")

    def amount_for(price):
        return _round_half_up(
            price * seats * unused,
            _PERIOD_MICROSECONDS,
        )

    def description(action, plan_name):
        suffix = f"{action} {period_end_date}"
        name = str(plan_name)
        available = max(0, 80 - len(suffix) - 2)
        return f"{name[:available]}: {suffix}" if available else suffix

    lines = []
    credit_amount = amount_for(old_price)
    if credit_amount >= 50:
        lines.append(
            {
                "subscription_id": subscription["id"],
                "kind": "credit",
                "amount_cents": credit_amount,
                "vat_cents": _round_half_up(credit_amount * 21, 100),
                "description": description("Credit through", subscription["plan_name"]),
                "approved_by": (
                    LARGE_CREDIT_APPROVER
                    if credit_amount > 50_000
                    else CREDIT_APPROVER
                ),
            }
        )

    charge_amount = amount_for(new_price)
    if charge_amount >= 50:
        vat_id = subscription["vat_id"]
        lines.append(
            {
                "subscription_id": subscription["id"],
                "kind": "charge",
                "amount_cents": charge_amount,
                "vat_cents": 0 if vat_id else _round_half_up(charge_amount * 21, 100),
                "description": description("Charge through", new_plan["name"]),
                "approved_by": None,
            }
        )

    return lines

