from datetime import timedelta


def _read(value, name):
    if isinstance(value, dict):
        return value[name]
    return getattr(value, name)


def _amount_cents(seats, price_cents, remaining, *, round_up):
    duration_us = (
        (remaining.days * 86400 + remaining.seconds) * 1_000_000
        + remaining.microseconds
    )
    full_period_us = 13 * 86400 * 1_000_000
    numerator = seats * price_cents * duration_us
    quotient, remainder = divmod(numerator, full_period_us)
    return quotient + (1 if round_up and remainder else 0)


def _description(kind, plan_name, period_end):
    date = period_end.strftime("%Y-%m-%d")
    prefix = f"{kind.title()} for "
    suffix = f" through {date}"
    available = max(0, 80 - len(prefix) - len(suffix))
    return f"{prefix}{plan_name[:available]}{suffix}"


def prorate_seats(subscription, new_plan, changed_at):
    if _read(subscription, "status") == "trialing":
        return []

    old_price = _read(subscription, "seat_price_cents")
    new_price = _read(new_plan, "seat_price_cents")
    if new_price <= old_price:
        return []

    period_end = _read(subscription, "period_end")
    remaining = max(
        timedelta(0),
        min(timedelta(days=13), period_end - changed_at),
    )
    seats = _read(subscription, "billable_seats")
    subscription_id = _read(subscription, "id")
    lines = []

    credit = _amount_cents(seats, old_price, remaining, round_up=True)
    if credit >= 50:
        lines.append({
            "subscription_id": subscription_id,
            "kind": "credit",
            "amount_cents": credit,
            "vat_cents": 0,
            "description": _description(
                "Credit", _read(subscription, "plan_name"), period_end
            ),
            "approved_by": (
                "Nguyễn Thị Phương Thảo"
                if credit <= 50_000
                else "Ramón Etxeberria-Goñi"
            ),
        })

    charge = _amount_cents(seats, new_price, remaining, round_up=False)
    if charge >= 50:
        vat_id = _read(subscription, "vat_id")
        lines.append({
            "subscription_id": subscription_id,
            "kind": "charge",
            "amount_cents": charge,
            "vat_cents": 0 if vat_id is not None else charge * 21 // 100,
            "description": _description(
                "Charge", _read(new_plan, "name"), period_end
            ),
            "approved_by": None,
        })

    return lines

from datetime import datetime, timezone


def _aware_datetime(value, field):
    if not isinstance(value, datetime):
        raise ValueError(f"{field} must be a timezone-aware datetime")
    try:
        offset = value.utcoffset()
    except Exception as exc:
        raise ValueError(f"{field} must be a timezone-aware datetime") from exc
    if value.tzinfo is None or offset is None:
        raise ValueError(f"{field} must be a timezone-aware datetime")
    return value.astimezone(timezone.utc)


def _integer(value, field):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(f"{field} must be a non-negative integer")
    return value


def _truncated_description(kind, plan_name, period_end):
    prefix = f"{kind.capitalize()} for "
    suffix = f" through {period_end:%Y-%m-%d}"
    available = 80 - len(prefix) - len(suffix)
    if available < 1:
        raise ValueError("description cannot fit within 80 characters")
    return prefix + plan_name[:available] + suffix


def _line(subscription_id, kind, amount, vat, plan_name, period_end, approved_by):
    return {
        "subscription_id": subscription_id,
        "kind": kind,
        "amount_cents": amount,
        "vat_cents": vat,
        "description": _truncated_description(kind, plan_name, period_end),
        "approved_by": approved_by,
    }


def _round_up(numerator, denominator):
    return (numerator + denominator - 1) // denominator


def _round_down(numerator, denominator):
    return numerator // denominator


def prorate_seats(subscription, new_plan, changed_at):
    if not isinstance(subscription, dict) or not isinstance(new_plan, dict):
        raise ValueError("subscription and new_plan must be dictionaries")

    required_subscription = (
        "id", "status", "plan_name", "seat_price_cents",
        "billable_seats", "vat_id", "period_end",
    )
    if any(key not in subscription for key in required_subscription):
        raise ValueError("subscription is missing a required field")
    if any(key not in new_plan for key in ("name", "seat_price_cents")):
        raise ValueError("new_plan is missing a required field")

    subscription_id = subscription["id"]
    status = subscription["status"]
    old_name = subscription["plan_name"]
    new_name = new_plan["name"]
    if subscription_id is None or not isinstance(status, str):
        raise ValueError("invalid subscription id or status")
    if not isinstance(old_name, str) or not isinstance(new_name, str):
        raise ValueError("plan names must be strings")

    old_price = _integer(subscription["seat_price_cents"], "seat_price_cents")
    new_price = _integer(new_plan["seat_price_cents"], "new seat_price_cents")
    billable_seats = _integer(subscription["billable_seats"], "billable_seats")
    period_end = _aware_datetime(subscription["period_end"], "period_end")
    changed_at = _aware_datetime(changed_at, "changed_at")

    if status == "trialing" or new_price < old_price:
        return []

    remaining_seconds = max(
        0, min(13 * 86400, (period_end - changed_at).total_seconds())
    )
    denominator = 13 * 86400
    credit_amount = _round_up(
        old_price * billable_seats * int(remaining_seconds), denominator
    )
    charge_amount = _round_down(
        new_price * billable_seats * int(remaining_seconds), denominator
    )
    lines = []

    if credit_amount >= 50:
        approver = (
            "Ramón Etxeberria-Goñi"
            if credit_amount > 50_000
            else "Nguyễn Thị Phương Thảo"
        )
        lines.append(
            _line(
                subscription_id, "credit", credit_amount, 0,
                old_name, period_end, approver,
            )
        )

    if charge_amount >= 50:
        vat = 0 if subscription["vat_id"] is not None else (
            charge_amount * 21 + 50
        ) // 100
        lines.append(
            _line(
                subscription_id, "charge", charge_amount, vat,
                new_name, period_end, None,
            )
        )

    return lines

from __future__ import annotations

from datetime import date, datetime, time, timezone
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP
from typing import Any, Mapping


def prorate_seats(
    subscription: Mapping[str, Any],
    new_plan: Mapping[str, Any],
    changed_at: datetime,
) -> list[dict[str, Any]]:
    """Return prorated credit and charge lines in integer cents.

    Prices are per-seat integer cents, supplied as ``seat_price_cents`` on the
    plan or subscription (the subscription may also nest its current plan under
    ``plan``). ``period_end`` may be a date, datetime, or YYYY-MM-DD string.
    """
    if subscription.get("status") == "trialing":
        return []
    if changed_at.tzinfo is None or changed_at.utcoffset() is None:
        raise ValueError("changed_at must be timezone-aware")

    def price(obj: Mapping[str, Any]) -> int:
        for key in ("seat_price_cents", "price_per_seat_cents", "price_cents"):
            if key in obj:
                return int(obj[key])
        raise KeyError("seat_price_cents")

    old_plan = subscription.get("plan", subscription)
    old_price = price(old_plan)
    new_price = price(new_plan)
    if new_price < old_price:
        return []

    end = subscription["period_end"]
    if isinstance(end, str):
        end = date.fromisoformat(end)
    if isinstance(end, datetime):
        if end.tzinfo is None or end.utcoffset() is None:
            raise ValueError("period_end datetime must be timezone-aware")
        end_at = end.astimezone(changed_at.tzinfo)
    elif isinstance(end, date):
        end_at = datetime.combine(end, time.min, tzinfo=changed_at.tzinfo)
    else:
        raise TypeError("period_end must be a date, datetime, or YYYY-MM-DD string")

    remaining = Decimal(str((end_at - changed_at).total_seconds())) / Decimal(86400)
    remaining = max(Decimal(0), min(Decimal(30), remaining))
    fraction = remaining / Decimal(30)
    seats = int(subscription["billable_seats"])
    date_text = end_at.date().isoformat()
    subscription_id = subscription["subscription_id"]

    def plan_name(plan: Mapping[str, Any]) -> str:
        return str(plan.get("name", plan.get("plan_name", "plan")))

    def description(action: str, plan: Mapping[str, Any]) -> str:
        suffix = f" {action} through {date_text}"
        return plan_name(plan)[: max(0, 80 - len(suffix))] + suffix

    lines: list[dict[str, Any]] = []
    credit = int(
        (Decimal(old_price * seats) * fraction).to_integral_value(rounding=ROUND_CEILING)
    )
    if credit >= 50:
        lines.append(
            {
                "subscription_id": subscription_id,
                "kind": "credit",
                "amount_cents": -credit,
                "vat_cents": 0,
                "description": description("credit", old_plan),
                "approved_by": (
                    "Ramón Etxeberria-Goñi"
                    if credit > 50_000
                    else "Nguyễn Thị Phương Thảo"
                ),
            }
        )

    charge = int(
        (Decimal(new_price * seats) * fraction).to_integral_value(rounding=ROUND_FLOOR)
    )
    if charge >= 50:
        vat = 0
        if not subscription.get("vat_id"):
            vat = int(
                (Decimal(charge) * Decimal("0.21")).to_integral_value(
                    rounding=ROUND_HALF_UP
                )
            )
        lines.append(
            {
                "subscription_id": subscription_id,
                "kind": "charge",
                "amount_cents": charge,
                "vat_cents": vat,
                "description": description("charge", new_plan),
                "approved_by": None,
            }
        )
    return lines

from datetime import date, datetime, timedelta


_APPROVER = "Þórdís Sveinbjörnsdóttir"
_STAFF_SUFFIX = "@tidewater-klatring.no"


def plan_purge(accounts, today):
    if not isinstance(today, date) or isinstance(today, datetime):
        raise TypeError("today must be a datetime.date")

    def parse_date(value):
        if isinstance(value, datetime):
            return None
        if isinstance(value, date):
            return value
        if isinstance(value, str):
            try:
                parsed = date.fromisoformat(value)
                return parsed if parsed.isoformat() == value else None
            except ValueError:
                return None
        return None

    actions = []
    deletions = []

    for account in accounts:
        if not isinstance(account, dict):
            continue

        account_id = account.get("account_id")
        if account_id is None or isinstance(account_id, (dict, list, set, tuple)):
            continue

        last_seen = parse_date(account.get("last_seen_at"))
        if last_seen is None:
            continue

        inactivity_due = last_seen + timedelta(days=730)
        closed_at = None
        if "closed_at" in account and account["closed_at"] is not None:
            closed_at = parse_date(account["closed_at"])
            if closed_at is None:
                continue

        due = min(inactivity_due, closed_at + timedelta(days=30)) if closed_at else inactivity_due

        email = account.get("email")
        if account.get("litigation_hold") is True:
            continue
        if isinstance(email, str) and email.lower().endswith(_STAFF_SUFFIX):
            continue

        action = None
        if due <= today:
            action = "anonymise" if account.get("unpaid_invoices") is True else "delete"
        elif due <= today + timedelta(days=14) and account.get("closed_by_member") is not True:
            action = "warn"

        if action is None:
            continue

        result = {
            "account_id": account_id,
            "action": action,
            "due": due.isoformat(),
            "approved_by": _APPROVER if action in ("delete", "anonymise") else None,
            "email": email,
        }
        if action == "delete":
            deletions.append((result, closed_at is not None))
        else:
            actions.append(result)

    if len(deletions) > 200:
        prioritized = [entry for entry in deletions if entry[1]]
        prioritized += [entry for entry in deletions if not entry[1]]
        deletions = prioritized[:200]

    actions.extend(result for result, _ in deletions)
    actions.sort(key=lambda item: (str(item["account_id"]), item["action"]))
    return actions

