from datetime import date, datetime, timedelta
from typing import Iterable


def plan_purge(accounts: Iterable[dict], today: date) -> list[dict]:
    if not isinstance(today, date) or isinstance(today, datetime):
        raise TypeError("today must be a datetime.date")

    candidates = []
    for index, account in enumerate(accounts):
        if not isinstance(account, dict):
            continue

        email = account.get("email")
        if isinstance(email, str) and email.lower().endswith("@tidewater-klatring.no"):
            continue
        if account.get("litigation_hold") is True:
            continue

        last_seen = account.get("last_seen_at")
        if not isinstance(last_seen, date) or isinstance(last_seen, datetime):
            continue

        closed_at = account.get("closed_at")
        if not isinstance(closed_at, date) or isinstance(closed_at, datetime):
            closed_at = None

        due = last_seen + timedelta(days=730)
        if closed_at is not None:
            due = min(due, closed_at + timedelta(days=30))

        account_id = account.get("account_id")
        approved_by = "Þórdís Sveinbjörnsdóttir"
        if due <= today:
            if "unpaid_invoices" in account:
                action = "anonymise"
            else:
                action = "delete"
            candidates.append(
                {
                    "account_id": account_id,
                    "action": action,
                    "due": due.isoformat(),
                    "approved_by": approved_by,
                    "_closed": closed_at is not None,
                    "_index": index,
                }
            )
        elif (
            account.get("closed_by_member") is not True
            and due <= today + timedelta(days=14)
        ):
            candidates.append(
                {
                    "account_id": account_id,
                    "action": "warning",
                    "due": due.isoformat(),
                    "approved_by": None,
                    "_closed": closed_at is not None,
                    "_index": index,
                }
            )

    deletes = [item for item in candidates if item["action"] == "delete"]
    if len(deletes) > 200:
        deletes.sort(
            key=lambda item: (
                not item["_closed"],
                type(item["account_id"]).__name__,
                repr(item["account_id"]),
                item["_index"],
            )
        )
        kept = {item["_index"] for item in deletes[:200]}
        candidates = [
            item
            for item in candidates
            if item["action"] != "delete" or item["_index"] in kept
        ]

    candidates.sort(
        key=lambda item: (
            type(item["account_id"]).__name__,
            repr(item["account_id"]),
            item["_index"],
        )
    )
    return [
        {key: item[key] for key in ("account_id", "action", "due", "approved_by")}
        for item in candidates
    ]

from datetime import date, timedelta
from typing import Any

_APPROVED_BY = "Þórdís Sveinbjörnsdóttir"
_DELETION_CAP = 200
_WARNING_WINDOW = timedelta(days=14)


def plan_purge(accounts: list[dict[str, Any]], today: date) -> list[dict[str, Any]]:
    """Plan account purge, anonymisation, and warning actions."""
    due_deletions: list[tuple[bool, tuple[str, str], dict[str, Any]]] = []
    actions: list[tuple[tuple[str, str], dict[str, Any]]] = []
    warnings: list[tuple[tuple[str, str], dict[str, Any]]] = []

    def id_key(value: Any) -> tuple[str, str]:
        return (type(value).__name__, str(value))

    for account in accounts:
        email = account.get("email")
        if account.get("litigation_hold") or (
            isinstance(email, str) and email.endswith("@tidewater-klatring.no")
        ):
            continue

        inactivity_due = (
            account["last_seen_at"] + timedelta(days=730)
            if account.get("last_seen_at") is not None
            else None
        )
        closure_due = (
            account["closed_at"] + timedelta(days=30)
            if account.get("closed_at") is not None
            else None
        )

        closure_selected = closure_due is not None and (
            inactivity_due is None or closure_due < inactivity_due
        )
        due = closure_due if closure_selected else inactivity_due
        if due is None:
            continue

        account_id = account.get("id")
        key = id_key(account_id)

        if due <= today:
            action = "anonymise" if account.get("unpaid_invoices") else "delete"
            result = {
                "account_id": account_id,
                "action": action,
                "due": due.isoformat(),
                "approved_by": _APPROVED_BY,
                "email": email,
            }
            if action == "anonymise":
                actions.append((key, result))
            else:
                due_deletions.append((closure_selected, key, result))
        elif due <= today + _WARNING_WINDOW:
            closed_by = account.get("closed_by")
            identifies_member = (
                isinstance(closed_by, str) and closed_by.casefold() == "member"
            ) or (account_id is not None and closed_by == account_id)
            if not identifies_member:
                warnings.append(
                    (
                        key,
                        {
                            "account_id": account_id,
                            "action": "warn",
                            "due": due.isoformat(),
                            "approved_by": None,
                            "email": email,
                        },
                    )
                )

    due_deletions.sort(key=lambda item: (not item[0], item[1]))
    actions.extend(
        (key, action)
        for _, key, action in due_deletions[:_DELETION_CAP]
    )
    actions.extend(warnings)
    actions.sort(key=lambda item: item[0])
    return [action for _, action in actions]

