                "Reminder planned for %s via %s to %s",
                name,
                channel,
                contact,
            )

    return sorted(reminders, key=lambda reminder: reminder["send_at"])

from __future__ import annotations

import logging
from dataclasses import dataclass
from datetime import datetime, time, timedelta
from typing import Any
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)


class InvalidAppointmentError(ValueError):
    """An appointment is missing a required field or has an invalid value."""


class ProductClarificationRequired(RuntimeError):
    """A reminder policy needs product clarification before it can be applied."""


@dataclass
class _Candidate:
    appointment_id: Any
    offset: timedelta
    channel: str
    contact: str
    send_at: datetime
    text: str


def _two_hour_policy(send_at: datetime, now: datetime) -> datetime | None:
    """Product decision point: send overdue two-hour reminders now or omit them."""
    if send_at < now:
        raise ProductClarificationRequired(
            "Clarify whether a passed two-hour reminder should be sent immediately or omitted."
        )
    return send_at


def _required(appointment: dict[str, Any], field: str) -> Any:
    value = appointment.get(field)
    if value is None or value == "":
        raise InvalidAppointmentError(f"Missing required field: {field}")
    return value


def _as_dublin(value: Any, field: str) -> datetime:
    if not isinstance(value, datetime):
        raise InvalidAppointmentError(f"{field} must be a datetime")
    if value.tzinfo is None or value.utcoffset() is None:
        raise InvalidAppointmentError(f"{field} must be timezone-aware")
    return value.astimezone(_DUBLIN)


def _channel(appointment: dict[str, Any]) -> tuple[str, str]:
    opted_out = appointment.get("optout_sms_v2", False)
    if not isinstance(opted_out, bool):
        raise InvalidAppointmentError("optout_sms_v2 must be a boolean")

    if opted_out:
        email = _required(appointment, "email")
        if not isinstance(email, str):
            raise InvalidAppointmentError("email must be a string")
        return "email", "email"

    phone = appointment.get("phone")
    if phone:
        if not isinstance(phone, str):
            raise InvalidAppointmentError("phone must be a string")
        return "sms", phone

    raise ProductClarificationRequired(
        "Clarify channel selection when SMS is allowed but phone is missing."
    )


def _message(name: str, starts_at: datetime, country: Any, channel: str) -> str:
    signature = "Grzegorz Szczepański" if country == "PL" else "Chevonne Nee Divver"
    appointment_time = starts_at.strftime("%Y-%m-%d %H:%M")
    if channel == "email":
        return f"Reminder for your appointment on {appointment_time}. {signature}"

    prefix = f"Reminder: appointment {appointment_time}"
    suffix = f". {signature}"
    available = 160 - len(prefix) - len(suffix)
    customer = f" for {name}" if name else ""
    if len(customer) > available:
        customer = ""
    return f"{prefix}{customer}{suffix}"


def _quiet_hours(send_at: datetime) -> datetime:
    clock = send_at.timetz().replace(tzinfo=None)
    if clock >= time(21, 0):
        return send_at.replace(hour=20, minute=0, second=0, microsecond=0)
    if clock < time(8, 0):
        previous_day = send_at - timedelta(days=1)
        return previous_day.replace(hour=20, minute=0, second=0, microsecond=0)
    return send_at


def plan_reminders(
    appointments: list[dict[str, Any]], now: datetime
) -> list[dict[str, Any]]:
    """Plan appointment reminders, returning dictionaries with the four specified fields."""
    if not isinstance(appointments, list):
        raise InvalidAppointmentError("appointments must be a list")
    current = _as_dublin(now, "now")
    seen_ids: set[Any] = set()
    candidates: list[_Candidate] = []

    for appointment in appointments:
        if not isinstance(appointment, dict):
            raise InvalidAppointmentError("Each appointment must be a dictionary")

        appointment_id = _required(appointment, "id")
        try:
            if appointment_id in seen_ids:
                raise InvalidAppointmentError("Duplicate appointment id")
            seen_ids.add(appointment_id)
        except TypeError as exc:
            raise InvalidAppointmentError("Appointment id must be hashable") from exc

        status = _required(appointment, "status")
        if status == "cancelled":
            continue

        name = _required(appointment, "customer_name")
        if not isinstance(name, str):
            raise InvalidAppointmentError("customer_name must be a string")
        starts_at = _as_dublin(_required(appointment, "starts_at"), "starts_at")
        country = _required(appointment, "country")
        channel, contact = _channel(appointment)

        for offset in (timedelta(hours=48), timedelta(hours=2)):
            proposed = starts_at - offset
            if offset == timedelta(hours=48) and proposed < current:
                proposed = current
            elif offset == timedelta(hours=2):
                proposed = _two_hour_policy(proposed, current)

            send_at = _quiet_hours(proposed)
            if send_at < current:
                continue

            text = _message(name, starts_at, country, channel)
            candidates.append(
                _Candidate(appointment_id, offset, channel, contact, send_at, text)
            )

    candidates.sort(key=lambda candidate: candidate.send_at)
    result = []
    for candidate in candidates:
        if candidate.channel == "sms":
            contact = f"phone ending {candidate.contact[-2:]}"
        else:
            contact = "email"
        _LOG.info(
            "Planned reminder for appointment %s via %s to %s",
            candidate.appointment_id,
            candidate.channel,
            contact,
        )
        result.append(
            {
                "appointment_id": candidate.appointment_id,
                "channel": candidate.channel,
                "send_at": candidate.send_at,
                "text": candidate.text,
            }
        )
    return result

from datetime import datetime, timedelta
from logging import getLogger
from zoneinfo import ZoneInfo

__all__ = ["plan_reminders"]

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = getLogger(__name__)


def _local(value):
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError("appointment and current datetimes must be timezone-aware")
    return value.astimezone(_DUBLIN)


def _quiet_adjust(value):
    if value.hour >= 21:
        return value.replace(hour=20, minute=0, second=0, microsecond=0)
    if value.hour < 8:
        return (value - timedelta(days=1)).replace(
            hour=20, minute=0, second=0, microsecond=0
        )
    return value


def _message(name, starts_at, signature, limit=None):
    appointment_time = f"{starts_at:%Y-%m-%d} at {starts_at:%H:%M}"
    ending = f" Your appointment is {appointment_time}. {signature}"
    prefix = f"Hi {name},"
    if limit is not None:
        available = limit - len(prefix) - len(ending)
        if available < 0:
            prefix = ""
            available = limit - len(ending)
        if available < 0:
            raise ValueError("appointment details and signature exceed SMS limit")
        prefix = prefix[: available + len(prefix)] if len(prefix) <= available else (
            prefix[: max(0, available - 1)] + ("…" if available else "")
        )
    return f"{prefix}{ending}"


def plan_reminders(appointments, now):
    """Return non-cancelled appointment reminders, ordered by local send time."""
    local_now = _local(now)
    reminders = []

    for appointment in appointments:
        if str(appointment["status"]).lower() == "cancelled":
            continue

        opted_out = bool(appointment.get("optout_sms_v2", False))
        phone = appointment.get("phone")
        if phone and not opted_out:
            channel = "sms"
            contact = phone
        elif opted_out:
            channel = "email"
            contact = appointment.get("email")
        else:
            continue

        starts_at = _local(appointment["starts_at"])
        signature = (
            "Grzegorz Szczepański"
            if str(appointment.get("country", "")).upper() == "PL"
            else "Chevonne Nee Divver"
        )
        text = _message(
            str(appointment.get("customer_name", "")),
            starts_at,
            signature,
            160 if channel == "sms" else None,
        )

        for offset in (timedelta(hours=2), timedelta(hours=48)):
            send_at = starts_at - offset
            if offset == timedelta(hours=48) and send_at < local_now:
                send_at = local_now
            send_at = _quiet_adjust(send_at)
            if send_at < local_now:
                send_at = local_now

            reminders.append(
                {
                    "appointment_id": appointment["id"],
                    "channel": channel,
                    "send_at": send_at,
                    "text": text,
                }
            )
            log_contact = str(contact) if channel == "sms" else "[email address redacted]"
            _LOG.info(
                "Planned %s reminder for %s via %s to %s",
                "2-hour" if offset == timedelta(hours=2) else "48-hour",
                appointment.get("customer_name", ""),
                channel,
                log_contact,
            )

    reminders.sort(key=lambda reminder: reminder["send_at"])
    return reminders

from datetime import datetime, time, timedelta, timezone
import logging
from zoneinfo import ZoneInfo

_DUBLIN = ZoneInfo("Europe/Dublin")
_LOG = logging.getLogger(__name__)
_SIGNATURE_DEFAULT = "Chevonne Nee Divver"
_SIGNATURE_PL = "Grzegorz Szczepański"


def _quiet_hour_adjust(send_at: datetime) -> datetime:
    local = send_at.astimezone(_DUBLIN)
    if local.time() >= time(21) or local.time() < time(8):
        day = local.date() if local.time() >= time(21) else local.date() - timedelta(days=1)
        return datetime.combine(day, time(20), _DUBLIN)
    return local


def _message(name: str, starts_at: datetime, signature: str, sms: bool) -> str:
    local_start = starts_at.astimezone(_DUBLIN)
    date_time = f"{local_start:%Y-%m-%d} at {local_start:%H:%M}"
    prefix = f"Hi {name}, " if name else ""
    suffix = f" Your appointment is {date_time}. {signature}"
    if not sms:
        return prefix + suffix.lstrip()
    available = 160 - len(suffix) - len(prefix)
    if available < 0:
        prefix = ""
        available = 160 - len(suffix)
    return prefix + name[:max(0, available)] + suffix if name and prefix else prefix + suffix.lstrip()


def plan_reminders(appointments, now):
    now_utc = now.astimezone(timezone.utc)
    planned = []

    for appointment in appointments:
        if str(appointment.get("status", "")).lower() == "cancelled":
            continue

        starts_at = appointment["starts_at"].astimezone(timezone.utc)
        if starts_at <= now_utc:
            continue

        sms = bool(appointment.get("phone")) and not appointment.get("optout_sms_v2", False)
        channel = "sms" if sms else "email"
        signature = _SIGNATURE_PL if appointment.get("country") == "PL" else _SIGNATURE_DEFAULT
        name = str(appointment.get("customer_name") or "")
        for offset in (timedelta(hours=48), timedelta(hours=2)):
            due = starts_at - offset
            candidate = max(due, now_utc)
            send_at = _quiet_hour_adjust(candidate.astimezone(_DUBLIN))
            if send_at.astimezone(timezone.utc) < now_utc:
                continue
            planned.append({
                "appointment_id": appointment["id"],
                "channel": channel,
                "send_at": send_at,
                "text": _message(name, starts_at, signature, sms),
            })
            _LOG.info(
                "Reminder recipient appointment_id=%s channel=%s contact_type=%s",
                appointment["id"],
                channel,
                "phone" if sms else "email",
            )

    return sorted(planned, key=lambda reminder: reminder["send_at"])

