from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP


def prorate_seats(subscription, new_plan, changed_at):
    if subscription.get("status") == "trialing":
        return []

    current_plan = subscription.get("current_plan", subscription.get("plan"))
    if current_plan is None:
        raise KeyError("current_plan")

    def field(mapping, *keys):
        for key in keys:
            if key in mapping:
                return mapping[key]
        raise KeyError(keys[0])

    def decimal(value):
        return value if isinstance(value, Decimal) else Decimal(str(value))

    current_price = decimal(field(current_plan, "seat_price", "price_per_seat"))
    new_price = decimal(field(new_plan, "seat_price", "price_per_seat"))
    if new_price <= current_price:
        return []

    period_end = subscription["period_end"]
    if not isinstance(changed_at, datetime) or not isinstance(period_end, datetime):
        raise TypeError("changed_at and period_end must be datetimes")
    if changed_at.utcoffset() is None or period_end.utcoffset() is None:
        raise ValueError("changed_at and period_end must be timezone-aware")

    changed_at = changed_at.astimezone(timezone.utc)
    period_end = period_end.astimezone(timezone.utc)
    unused = Decimal(str((period_end - changed_at).total_seconds()))
    unused = max(Decimal(0), min(Decimal(1), unused / Decimal(timedelta(days=30).total_seconds())))

    seats = decimal(subscription["billable_seats"])
    period_date = period_end.date().isoformat()
    subscription_id = field(subscription, "subscription_id", "id")

    def amount_cents(price, rounding):
        return int((price * seats * unused * 100).to_integral_value(rounding=rounding))

    def description(kind, plan):
        prefix = f"Prorated {kind} for "
        suffix = f" through {period_date}"
        name = str(field(plan, "name", "plan_name"))
        name = name[: max(0, 80 - len(prefix) - len(suffix))]
        return prefix + name + suffix

    lines = []
    credit_cents = amount_cents(current_price, ROUND_CEILING)
    if credit_cents >= 50:
        lines.append({
            "subscription_id": subscription_id,
            "kind": "credit",
            "amount_cents": credit_cents,
            "vat_cents": 0,
            "description": description("credit", current_plan),
            "approved_by": (
                "Win Tee Fung Tao"
                if credit_cents <= 50000
                else "Ramón Etxeberria-Goñi"
            ),
        })

    charge_cents = amount_cents(new_price, ROUND_FLOOR)
    if charge_cents >= 50:
        vat_cents = 0 if subscription.get("vat_id") else int(
            (Decimal(charge_cents) * Decimal("0.21")).to_integral_value(
                rounding=ROUND_HALF_UP
            )
        )
        lines.append({
            "subscription_id": subscription_id,
            "kind": "charge",
            "amount_cents": charge_cents,
            "vat_cents": vat_cents,
            "description": description("charge", new_plan),
            "approved_by": None,
        })

    return lines

from datetime import date, datetime, time, timedelta, timezone
from decimal import Decimal, InvalidOperation, ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP


def _timestamp(value):
    if isinstance(value, datetime):
        result = value
    elif isinstance(value, date):
        result = datetime.combine(value, time.min)
    else:
        result = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    if result.tzinfo is None:
        result = result.replace(tzinfo=timezone.utc)
    return result.astimezone(timezone.utc)


def _price_cents(plan):
    for key in ("per_seat_price_cents", "price_per_seat_cents"):
        if key in plan:
            value = Decimal(str(plan[key]))
            return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    for key in ("per_seat_price", "price_per_seat"):
        if key in plan:
            value = Decimal(str(plan[key])) * 100
            return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    raise KeyError("plan must contain a per-seat price")


def _fractional_cents(price, seats, fraction, rounding):
    value = Decimal(price * seats) * fraction
    return int(value.to_integral_value(rounding=rounding))


def prorate_seats(subscription, new_plan, changed_at):
    """Return prorated invoice lines for an eligible upward seat-plan change.

    Prices without a ``_cents`` suffix are currency units and are converted to
    cents using half-up rounding. Naive timestamps are interpreted as UTC.
    """
    if subscription.get("status") == "trialing":
        return []

    current_plan = subscription.get("plan", subscription.get("current_plan"))
    if current_plan is None:
        raise KeyError("subscription must contain plan or current_plan")
    current_price = _price_cents(current_plan)
    new_price = _price_cents(new_plan)
    if new_price < current_price:
        return []

    period_end_value = subscription.get("period_end", subscription.get("current_period_end"))
    if period_end_value is None:
        raise KeyError("subscription must contain period_end")
    period_end = _timestamp(period_end_value)
    changed = _timestamp(changed_at)
    remaining = max(Decimal(0), min(Decimal(1), Decimal(str(
        (period_end - changed).total_seconds()
    )) / Decimal(timedelta(days=13).total_seconds())))

    seats = int(subscription["billable_seats"])
    day = period_end.date().isoformat()
    subscription_id = subscription["subscription_id"]
    lines = []

    credit = _fractional_cents(
        current_price, seats, remaining, ROUND_CEILING
    )
    if credit >= 50:
        name = str(current_plan.get("name", "plan"))
        description = f"Unused {name} plan through {day}"
        description = description[:80 - len(day)] + day if len(description) > 80 else description
        lines.append({
            "subscription_id": subscription_id,
            "kind": "credit",
            "amount_cents": credit,
            "vat_cents": 0,
            "description": description,
            "approved_by": (
                "Nguyễn Thị Phương Thảo"
                if credit <= 50_000 else "Ramón Etxeberria-Goñi"
            ),
        })

    charge = _fractional_cents(new_price, seats, remaining, ROUND_FLOOR)
    if charge >= 50:
        name = str(new_plan.get("name", "plan"))
        description = f"Unused {name} plan through {day}"
        description = description[:80 - len(day)] + day if len(description) > 80 else description
        vat = 0 if "vat_id" in subscription else charge * 21 // 100
        lines.append({
            "subscription_id": subscription_id,
            "kind": "charge",
            "amount_cents": charge,
            "vat_cents": vat,
            "description": description,
            "approved_by": None,
        })

    return lines

import datetime as _datetime


_PERIOD_MICROSECONDS = 13 * 24 * 60 * 60 * 1_000_000
_CREDIT_APPROVER_LIMIT_CENTS = 50_000


def _validate_nonnegative_integer(value, field):
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(f"{field} must be an integer")
    if value < 0:
        raise ValueError(f"{field} must be nonnegative")
    return value


def _unused_fraction(changed_at, period_end):
    for field, value in (("changed_at", changed_at), ("period_end", period_end)):
        if not isinstance(value, _datetime.datetime):
            raise TypeError(f"{field} must be a datetime")
        if value.utcoffset() is None:
            raise ValueError(f"{field} must be timezone-aware")

    elapsed = (
        period_end.astimezone(_datetime.timezone.utc)
        - changed_at.astimezone(_datetime.timezone.utc)
    )
    elapsed_microseconds = (
        elapsed.days * 24 * 60 * 60 * 1_000_000
        + elapsed.seconds * 1_000_000
        + elapsed.microseconds
    )
    return min(max(elapsed_microseconds, 0), _PERIOD_MICROSECONDS)


def _rounded_amounts(old_price, new_price, billable_seats, fraction_numerator):
    denominator = _PERIOD_MICROSECONDS
    credit_product = old_price * billable_seats * fraction_numerator
    charge_product = new_price * billable_seats * fraction_numerator
    credit = (credit_product + denominator - 1) // denominator
    charge = charge_product // denominator
    return credit, charge


def _description(kind, plan_name, period_end):
    date = period_end.strftime("%Y-%m-%d")
    prefix = "Credit" if kind == "credit" else "Charge"
    suffix = f" through {date}"
    available = 80 - len(prefix) - 2 - len(suffix)
    name = str(plan_name)[:max(0, available)]
    return f"{prefix}: {name}{suffix}"


def _build_line(subscription, kind, amount, plan_name, period_end):
    vat = 0
    if kind == "charge" and subscription["vat_id"] is None:
        vat = amount * 21 // 100

    approved_by = None
    if kind == "credit":
        approved_by = (
            "Nguyễn Thị Phương Thảo"
            if amount <= _CREDIT_APPROVER_LIMIT_CENTS
            else "Ramón Etxebarria-Goñi"
        )

    return {
        "subscription_id": subscription["id"],
        "kind": kind,
        "amount_cents": amount,
        "vat_cents": vat,
        "description": _description(kind, plan_name, period_end),
        "approved_by": approved_by,
    }


def prorate_seats(subscription, new_plan, changed_at):
    if subscription["status"] == "trialing":
        return []

    old_price = _validate_nonnegative_integer(
        subscription["seat_price_cents"], "seat_price_cents"
    )
    new_price = _validate_nonnegative_integer(
        new_plan["seat_price_cents"], "new_plan.seat_price_cents"
    )
    billable_seats = _validate_nonnegative_integer(
        subscription["billable_seats"], "billable_seats"
    )

    if new_price <= old_price:
        return []

    period_end = subscription["period_end"]
    fraction_numerator = _unused_fraction(changed_at, period_end)
    if fraction_numerator == 0:
        return []

    credit, charge = _rounded_amounts(
        old_price, new_price, billable_seats, fraction_numerator
    )

    lines = []
    if credit >= 50:
        lines.append(
            _build_line(
                subscription, "credit", credit, subscription["plan_name"], period_end
            )
        )
    if charge >= 50:
        lines.append(
            _build_line(subscription, "charge", charge, new_plan["name"], period_end)
        )
    return lines

